-- EDUVORA: ALL MATHS UPDATES (MTH 101 gap topics + CA workbook + MTH 102 two sets)
-- Paste this whole file into the Supabase SQL editor and click Run ONCE.
-- It only ADDS questions. Nothing is deleted or renamed. Repeats are skipped.

-- ============ PART 1: unn_mth101_additional_cbt_questions.sql ============
-- MTH 101: Elementary Mathematics I -- additional questions (old code MTH 111)
-- =============================================================================
-- 68 original questions on relations and sets of numbers, arithmetic and geometric
-- progressions, partial fractions, linear/quadratic/rational/absolute-value
-- inequalities, surds, indices and logarithms, the remainder and factor theorems,
-- quadratics, circular measure and compound angles, complex numbers and the
-- binomial theorem. They fill gaps in the existing MTH 101 bank (which already
-- covers sets, induction, complex numbers and trigonometry). Built from the topics in
-- the supplied MTH 101 / MTH 111 notes, revision questions and the NOUN course
-- text; all stems and numbers are original and every answer is computed. No
-- student compiler's name or wording is used. The textbooks were not copied.
-- ADDS ONLY: joins the existing MTH 101 subject; a question already present is
-- skipped, so running it twice is safe.
-- =============================================================================
with src (question, options, correct_index, explanation, topic) as (
values
  ('Let $K = \{1, 2, 3, 4, 5, 6, 7\}$ and define a relation $P$ on $K$ by $x\,P\,y$ if and only if $y = 3x + 2$. The range of $P$ is:', '["$\\{5\\}$","$\\{1, 2\\}$","$\\{5, 8\\}$","$\\{5, 7\\}$"]'::jsonb, 0, 'Both $x$ and $y$ must lie in $K$. $x = 1$ gives $y = 5$ (in $K$); $x = 2$ gives $y = 8$ (not in $K$). So the only pair is $(1, 5)$ and the range is $\{5\}$.', 'Relations'),
  ('On $L = \{1, 2, 3, 4, 5, 6\}$ a relation $R$ is defined by $x\,R\,y$ if $y = 2x + 1$. The domain of $R$ is:', '["$\\{1, 2, 3\\}$","$\\{1, 2\\}$","$\\{3, 5\\}$","$\\{1, 2, 3, 4, 5, 6\\}$"]'::jsonb, 1, 'Only $x = 1$ ($y = 3$) and $x = 2$ ($y = 5$) give values of $y$ in $L$, so the domain is $\{1, 2\}$.', 'Relations'),
  ('For the relation $R$ above ($y = 2x + 1$ on $L$), the range is:', '["$\\{1, 2\\}$","$\\{1, 3, 5\\}$","$\\{3, 5\\}$","$\\{2, 4, 6\\}$"]'::jsonb, 2, 'The pairs are $(1, 3)$ and $(2, 5)$, so the range (set of second elements) is $\{3, 5\}$.', 'Relations'),
  ('The relation $R$ on the integers defined by $x\,R\,y$ if $x - y$ is divisible by 3 is:', '["reflexive only","symmetric only","transitive only","an equivalence relation"]'::jsonb, 3, 'It is reflexive ($x - x = 0$), symmetric and transitive, so it is an equivalence relation (congruence modulo 3).', 'Relations'),
  ('If $R = \{(1, 2), (2, 3)\}$, the inverse relation $R^{-1}$ is:', '["$\\{(2, 1), (3, 2)\\}$","$\\{(1, 2), (2, 3)\\}$","$\\{(1, 3)\\}$","$\\{(2, 1), (3, 1)\\}$"]'::jsonb, 0, 'The inverse reverses each ordered pair.', 'Relations'),
  ('Which of the following is NOT correct?', '["$\\mathbb{R} - \\mathbb{Q} = \\mathbb{Q}^{\\prime}$","$\\mathbb{Z} \\cup \\mathbb{Q} = \\mathbb{Z}$","$\\mathbb{Z} \\cap \\mathbb{Q} = \\mathbb{Z}$","$\\mathbb{Z} \\cup \\mathbb{Q} = \\mathbb{Q}$"]'::jsonb, 1, 'Every integer is rational, so $\mathbb{Z} \subset \mathbb{Q}$ and $\mathbb{Z} \cup \mathbb{Q} = \mathbb{Q}$, not $\mathbb{Z}$.', 'Sets of Numbers'),
  ('$\mathbb{Q} \cup \mathbb{Q}^{\prime}$ (rationals together with irrationals) is the set of:', '["integers","natural numbers","real numbers","complex numbers"]'::jsonb, 2, 'The union of the rational and irrational numbers is $\mathbb{R}$.', 'Sets of Numbers'),
  ('Which of these numbers is irrational?', '["$\\sqrt{16}$","$0.\\overline{3}$","$\\dfrac{22}{7}$","$\\sqrt{18}$"]'::jsonb, 3, '$\sqrt{18} = 3\sqrt{2}$ cannot be written as a ratio of integers; the others are rational.', 'Sets of Numbers'),
  ('The correct chain of inclusions is:', '["$\\mathbb{N} \\subset \\mathbb{Z} \\subset \\mathbb{Q} \\subset \\mathbb{R}$","$\\mathbb{Q} \\subset \\mathbb{Z} \\subset \\mathbb{N} \\subset \\mathbb{R}$","$\\mathbb{Z} \\subset \\mathbb{N} \\subset \\mathbb{Q} \\subset \\mathbb{R}$","$\\mathbb{R} \\subset \\mathbb{Q} \\subset \\mathbb{Z} \\subset \\mathbb{N}$"]'::jsonb, 0, 'Each set is contained in the next larger number system.', 'Sets of Numbers'),
  ('Three numbers $a, b, c$ are in arithmetic progression. Their sum is 24 and their product is 270. The numbers are:', '["2, 8, 13","2.5, 8, 13.5","2, 4, 8","2.5, 13.5, 8.5"]'::jsonb, 1, 'Let the numbers be $m - d, m, m + d$. The sum gives $m = 8$. The product: $8(64 - d^{2}) = 270$, so $d^{2} = 30.25$ and $d = 5.5$. The numbers are 2.5, 8 and 13.5.', 'Arithmetic Progression'),
  ('Three numbers in arithmetic progression have sum 30 and product 750. The smallest of the three is:', '["4","6","5","3"]'::jsonb, 2, 'The middle term is 10. $10(100 - d^{2}) = 750$ gives $d^{2} = 25$, so $d = 5$. The numbers are 5, 10, 15.', 'Arithmetic Progression'),
  ('The 20th term of the arithmetic progression 7, 11, 15, ... is:', '["87","79","91","83"]'::jsonb, 3, '$T_{n} = a + (n - 1)d = 7 + 19(4) = 83$.', 'Arithmetic Progression'),
  ('The sum of the first 20 terms of the progression 7, 11, 15, ... is:', '["900","830","780","1020"]'::jsonb, 0, '$S_{n} = \tfrac{n}{2}[2a + (n - 1)d] = 10[14 + 76] = 900$.', 'Arithmetic Progression'),
  ('The first term of an arithmetic progression is 7 and the common difference is 4. Which term is the first to exceed 200?', '["the 49th term","the 50th term","the 51st term","the 48th term"]'::jsonb, 1, '$7 + (n - 1)4 > 200$ gives $n - 1 > 48.25$, so $n = 50$ (the 50th term is 203).', 'Arithmetic Progression'),
  ('The 8th term of the geometric progression 3, 6, 12, ... is:', '["192","768","384","256"]'::jsonb, 2, '$T_{n} = ar^{n-1} = 3(2)^{7} = 384$.', 'Geometric Progression'),
  ('The sum of the first 8 terms of the geometric progression 3, 6, 12, ... is:', '["768","381","1530","765"]'::jsonb, 3, '$S_{n} = \dfrac{a(r^{n} - 1)}{r - 1} = 3(255) = 765$.', 'Geometric Progression'),
  ('The sum to infinity of the geometric series $12 + 4 + \tfrac{4}{3} + \dots$ is:', '["18","16","24","12"]'::jsonb, 0, '$r = \tfrac{1}{3}$, so $S_{\infty} = \dfrac{a}{1 - r} = \dfrac{12}{2/3} = 18$.', 'Geometric Progression'),
  ('A sequence is defined by $U_{n} = 7 + 3U_{n-2}$. If $U_{5} = 35 + U_{3}$, the value of $U_{1}$ is:', '["28","7/3","7","7/12"]'::jsonb, 1, '$U_{5} = 7 + 3U_{3}$, so $7 + 3U_{3} = 35 + U_{3}$ gives $U_{3} = 14$. Then $14 = 7 + 3U_{1}$ gives $U_{1} = 7/3$.', 'Sequences'),
  ('For the sequence with general term $T_{n} = \dfrac{3 - 2n}{7}$, the 5th term is:', '["13/7","-15/7","-1","-7"]'::jsonb, 2, '$T_{5} = \dfrac{3 - 10}{7} = -1$.', 'Sequences'),
  ('For the same sequence ($T_{n} = \frac{3 - 2n}{7}$), the 5th partial sum $S_{5}$ is:', '["-1","13/7","-7","-15/7"]'::jsonb, 3, '$S_{5} = \dfrac{(1) + (-1) + (-3) + (-5) + (-7)}{7} = \dfrac{-15}{7}$.', 'Sequences'),
  ('Three numbers are in geometric progression with product 216 and sum 21. The middle number is:', '["6","3","9","12"]'::jsonb, 0, 'Writing the numbers as $a/r$, $a$, $ar$, the product is $a^{3} = 216$, so $a = 6$.', 'Geometric Progression'),
  ('Resolve $\dfrac{x+5}{(x - 1)(x - 2)}$ into partial fractions.', '["$\\dfrac{7}{x - 1} + \\dfrac{-6}{x - 2}$","$\\dfrac{-6}{x - 1} + \\dfrac{7}{x - 2}$","$\\dfrac{6}{x - 1} + \\dfrac{-7}{x - 2}$","$\\dfrac{-5}{x - 1} + \\dfrac{7}{x - 2}$"]'::jsonb, 1, 'Write $\dfrac{1x + 5}{(x - 1)(x - 2)} = \dfrac{A}{x - 1} + \dfrac{B}{x - 2}$. Cover-up: $A = \dfrac{1(1) + 5}{1 - 2} = -6$ and $B = \dfrac{1(2) + 5}{2 - 1} = 7$.', 'Partial Fractions'),
  ('Resolve $\dfrac{3x+1}{(x - 2)(x + 1)}$ into partial fractions.', '["$\\dfrac{(2/3)}{x - 2} + \\dfrac{(7/3)}{x + 1}$","$\\dfrac{(-7/3)}{x - 2} + \\dfrac{(-2/3)}{x + 1}$","$\\dfrac{(7/3)}{x - 2} + \\dfrac{(2/3)}{x + 1}$","$\\dfrac{(10/3)}{x - 2} + \\dfrac{(2/3)}{x + 1}$"]'::jsonb, 2, 'Write $\dfrac{3x + 1}{(x - 2)(x - -1)} = \dfrac{A}{x - 2} + \dfrac{B}{x - -1}$. Cover-up: $A = \dfrac{3(2) + 1}{2 - -1} = 7/3$ and $B = \dfrac{3(-1) + 1}{-1 - 2} = 2/3$.', 'Partial Fractions'),
  ('Resolve $\dfrac{2x-3}{(x - 3)(x - 1)}$ into partial fractions.', '["$\\dfrac{(1/2)}{x - 3} + \\dfrac{(3/2)}{x - 1}$","$\\dfrac{(-3/2)}{x - 3} + \\dfrac{(-1/2)}{x - 1}$","$\\dfrac{(5/2)}{x - 3} + \\dfrac{(1/2)}{x - 1}$","$\\dfrac{(3/2)}{x - 3} + \\dfrac{(1/2)}{x - 1}$"]'::jsonb, 3, 'Write $\dfrac{2x + -3}{(x - 3)(x - 1)} = \dfrac{A}{x - 3} + \dfrac{B}{x - 1}$. Cover-up: $A = \dfrac{2(3) + -3}{3 - 1} = 3/2$ and $B = \dfrac{2(1) + -3}{1 - 3} = 1/2$.', 'Partial Fractions'),
  ('Resolve $\dfrac{5x+7}{(x - 1)(x + 2)}$ into partial fractions.', '["$\\dfrac{4}{x - 1} + \\dfrac{1}{x + 2}$","$\\dfrac{1}{x - 1} + \\dfrac{4}{x + 2}$","$\\dfrac{-4}{x - 1} + \\dfrac{-1}{x + 2}$","$\\dfrac{5}{x - 1} + \\dfrac{1}{x + 2}$"]'::jsonb, 0, 'Write $\dfrac{5x + 7}{(x - 1)(x - -2)} = \dfrac{A}{x - 1} + \dfrac{B}{x - -2}$. Cover-up: $A = \dfrac{5(1) + 7}{1 - -2} = 4$ and $B = \dfrac{5(-2) + 7}{-2 - 1} = 1$.', 'Partial Fractions'),
  ('Resolve $\dfrac{x + 1}{(x - 1)(x^{2} + 1)}$ into partial fractions.', '["$\\dfrac{1}{x - 1} + \\dfrac{x}{x^{2} + 1}$","$\\dfrac{1}{x - 1} - \\dfrac{x}{x^{2} + 1}$","$\\dfrac{-1}{x - 1} + \\dfrac{x}{x^{2} + 1}$","$\\dfrac{-1}{x - 1} - \\dfrac{x}{x^{2} + 1}$"]'::jsonb, 1, 'Set $\dfrac{x+1}{(x-1)(x^{2}+1)} = \dfrac{A}{x-1} + \dfrac{Bx + C}{x^{2}+1}$. At $x = 1$: $A = 2/2 = 1$. Comparing $x^{2}$: $A + B = 0$, so $B = -1$. Constant: $A - C = 1$, so $C = 0$.', 'Partial Fractions'),
  ('Resolve $\dfrac{1}{(x - 1)(x - 2)^{2}}$ into partial fractions.', '["$\\dfrac{1}{x - 1} + \\dfrac{1}{x - 2} + \\dfrac{1}{(x - 2)^{2}}$","$\\dfrac{1}{x - 1} - \\dfrac{1}{x - 2} - \\dfrac{1}{(x - 2)^{2}}$","$\\dfrac{1}{x - 1} - \\dfrac{1}{x - 2} + \\dfrac{1}{(x - 2)^{2}}$","$-\\dfrac{1}{x - 1} + \\dfrac{1}{x - 2} + \\dfrac{1}{(x - 2)^{2}}$"]'::jsonb, 2, 'Write $\dfrac{A}{x-1} + \dfrac{B}{x-2} + \dfrac{C}{(x-2)^{2}}$. At $x = 1$: $A = 1$. At $x = 2$: $C = 1$. Comparing $x^{2}$ coefficients: $A + B = 0$, so $B = -1$.', 'Partial Fractions'),
  ('A rational function $\dfrac{p(x)}{q(x)}$ is called a proper fraction when:', '["the degree of $p$ is greater than that of $q$","$p$ and $q$ have the same factors","$q(x)$ is a constant","the degree of $p$ is less than the degree of $q$"]'::jsonb, 3, 'An improper fraction must first be divided out to give a polynomial plus a proper fraction.', 'Partial Fractions'),
  ('A linear factor $(x - \alpha)$ in the denominator of a proper fraction gives a partial fraction of the form:', '["$\\dfrac{A}{x - \\alpha}$","$\\dfrac{Ax + B}{x - \\alpha}$","$\\dfrac{A}{(x - \\alpha)^{2}}$ only","$A(x - \\alpha)$"]'::jsonb, 0, 'A repeated factor $(x - \alpha)^{2}$ gives two terms; an irreducible quadratic gives $\frac{Ax + B}{x^{2} + \dots}$.', 'Partial Fractions'),
  ('Dividing $x^{2} + 3x + 1$ by $x + 1$ gives a quotient and a remainder of:', '["$x + 2$ and $1$","$x + 2$ and $-1$","$x + 3$ and $-2$","$x - 2$ and $-1$"]'::jsonb, 1, '$x^{2} + 3x + 1 = (x + 1)(x + 2) - 1$.', 'Polynomial Division'),
  ('The solution of $3x + 3 \geq 4x + 12$ is:', '["$[-9, \\infty)$","$(-\\infty, -9)$","$(-\\infty, -9]$","$[9, \\infty)$"]'::jsonb, 2, '$3x - 4x \geq 12 - 3$ gives $-x \geq 9$; dividing by $-1$ reverses the sign: $x \leq -9$.', 'Linear Inequalities'),
  ('The solution set of $2x - 5 < 7$ is:', '["$x > 6$","$x < 1$","$x > 1$","$x < 6$"]'::jsonb, 3, '$2x < 12$, so $x < 6$.', 'Linear Inequalities'),
  ('The solution of $x^{2} - 5x + 6 < 0$ is:', '["$2 < x < 3$","$x < 2$ or $x > 3$","$x < -3$ or $x > -2$","$-3 < x < -2$"]'::jsonb, 0, '$x^{2} - 5x + 6 = (x - 2)(x - 3)$ is negative between its roots.', 'Quadratic Inequalities'),
  ('The solution of $x^{2} - 4 \geq 0$ is:', '["$-2 \\leq x \\leq 2$","$x \\leq -2$ or $x \\geq 2$","$x \\geq 2$ only","$x \\leq -2$ only"]'::jsonb, 1, '$(x - 2)(x + 2) \geq 0$ holds outside the roots.', 'Quadratic Inequalities'),
  ('The solution of $\dfrac{x - 1}{x + 2} > 0$ is:', '["$-2 < x < 1$","$x > 1$ only","$x < -2$ or $x > 1$","$x > -2$"]'::jsonb, 2, 'The sign changes at $x = -2$ and $x = 1$; the quotient is positive when both factors have the same sign.', 'Rational Inequalities'),
  ('The solution of $|2x - 3| < 5$ is:', '["$x < -1$ or $x > 4$","$-4 < x < 1$","$1 < x < 4$","$-1 < x < 4$"]'::jsonb, 3, '$-5 < 2x - 3 < 5$ gives $-2 < 2x < 8$, so $-1 < x < 4$.', 'Absolute Value Inequalities'),
  ('The solution of $|x + 1| \geq 3$ is:', '["$x \\leq -4$ or $x \\geq 2$","$-4 \\leq x \\leq 2$","$x \\geq 2$ only","$x \\leq -4$ only"]'::jsonb, 0, '$x + 1 \geq 3$ or $x + 1 \leq -3$.', 'Absolute Value Inequalities'),
  ('Simplify $\dfrac{2 - \sqrt{3}}{\sqrt{27} - \sqrt{3}}$.', '["$\\dfrac{2 - \\sqrt{3}}{2\\sqrt{3}} \\cdot 2$","$\\dfrac{2\\sqrt{3} - 3}{6}$","$\\dfrac{3 - 2\\sqrt{3}}{6}$","$\\dfrac{2\\sqrt{3} + 3}{6}$"]'::jsonb, 1, '$\sqrt{27} - \sqrt{3} = 3\sqrt{3} - \sqrt{3} = 2\sqrt{3}$. Then $\dfrac{2 - \sqrt{3}}{2\sqrt{3}} \times \dfrac{\sqrt{3}}{\sqrt{3}} = \dfrac{2\sqrt{3} - 3}{6}$.', 'Surds'),
  ('Rationalise the denominator of $\dfrac{1}{2 - \sqrt{3}}$.', '["$2 - \\sqrt{3}$","$\\dfrac{2 + \\sqrt{3}}{7}$","$2 + \\sqrt{3}$","$\\sqrt{3} - 2$"]'::jsonb, 2, 'Multiply by $\dfrac{2 + \sqrt{3}}{2 + \sqrt{3}}$: the denominator becomes $4 - 3 = 1$. (Check: $1/(2 - 1.732) = 3.732$.)', 'Surds'),
  ('Simplify $\sqrt{50} + \sqrt{18} - \sqrt{8}$.', '["$5\\sqrt{2}$","$7\\sqrt{2}$","$4\\sqrt{2}$","$6\\sqrt{2}$"]'::jsonb, 3, '$5\sqrt{2} + 3\sqrt{2} - 2\sqrt{2} = 6\sqrt{2}$.', 'Surds'),
  ('Evaluate $\log_{2} 32$.', '["5","4","6","16"]'::jsonb, 0, '$2^{5} = 32$.', 'Logarithms'),
  ('Evaluate $\log_{10} 5 + \log_{10} 20$.', '["1","2","25","100"]'::jsonb, 1, '$\log_{10}(5 \times 20) = \log_{10} 100 = 2$.', 'Logarithms'),
  ('If $\log_{3} x = 4$, then $x$ equals:', '["12","64","81","7"]'::jsonb, 2, '$x = 3^{4} = 81$.', 'Logarithms'),
  ('Simplify $\dfrac{2^{n+2} - 2^{n}}{2^{n}}$.', '["2","4","$2^{n}$","3"]'::jsonb, 3, '$\dfrac{2^{n}(4 - 1)}{2^{n}} = 3$.', 'Indices'),
  ('If $9^{x} = 27$, then $x$ equals:', '["3/2","2","3","1/3"]'::jsonb, 0, '$3^{2x} = 3^{3}$, so $2x = 3$ and $x = \tfrac{3}{2}$.', 'Indices'),
  ('When $x^{3} - 2x^{2} + x - 5$ is divided by $x - 2$, the remainder is:', '["3","-3","-5","0"]'::jsonb, 1, 'By the remainder theorem, the remainder is $f(2) = 8 - 8 + 2 - 5 = -3$.', 'Remainder Theorem'),
  ('The value of $k$ for which $x - 1$ is a factor of $x^{3} + kx^{2} - 4x + 2$ is:', '["-1","2","1","-2"]'::jsonb, 2, '$f(1) = 1 + k - 4 + 2 = 0$ gives $k = 1$.', 'Factor Theorem'),
  ('The sum of the roots of a quadratic equation is 5 and the sum of their squares is 53. The equation is:', '["$5x^{2} - x - 14 = 0$","$x^{2} - 14x + 5 = 0$","$x^{2} + 5x - 14 = 0$","$x^{2} - 5x - 14 = 0$"]'::jsonb, 3, '$\alpha\beta = \dfrac{(\alpha + \beta)^{2} - (\alpha^{2} + \beta^{2})}{2} = \dfrac{25 - 53}{2} = -14$. The equation is $x^{2} - 5x + (-14) = 0$.', 'Quadratic Equations'),
  ('The roots of $x^{2} + px + q = 0$ are real and equal when:', '["$p = \\pm 2\\sqrt{q}$","$p = \\pm 4q$","$p = \\pm 4\\sqrt{q}$","$p = \\pm 2q$"]'::jsonb, 0, 'Equal roots need $p^{2} - 4q = 0$, so $p^{2} = 4q$ and $p = \pm 2\sqrt{q}$.', 'Quadratic Equations'),
  ('If $n-1\,P_{3} : {}^{n}P_{4} = 1 : 6$, then $n$ equals:', '["3","6","4","5"]'::jsonb, 1, '${}^{n-1}P_{3} = (n-1)(n-2)(n-3)$ and ${}^{n}P_{4} = n(n-1)(n-2)(n-3)$. The ratio is $1/n$, so $n = 6$.', 'Permutations'),
  ('Convert $660^{\circ}$ to radians.', '["$\\dfrac{22\\pi}{3}$","$\\dfrac{11\\pi}{6}$","$\\dfrac{11\\pi}{3}$","$\\dfrac{5\\pi}{3}$"]'::jsonb, 2, '$660 \times \dfrac{\pi}{180} = \dfrac{11\pi}{3}$.', 'Circular Measure'),
  ('Convert $\dfrac{5\pi}{6}$ radians to degrees.', '["$120^{\\circ}$","$135^{\\circ}$","$300^{\\circ}$","$150^{\\circ}$"]'::jsonb, 3, '$\dfrac{5\pi}{6} \times \dfrac{180}{\pi} = 150$.', 'Circular Measure'),
  ('Evaluate $\cos 165^{\circ}$.', '["$-\\dfrac{\\sqrt{6} + \\sqrt{2}}{4}$","$\\dfrac{\\sqrt{6} + \\sqrt{2}}{4}$","$\\dfrac{\\sqrt{6} - \\sqrt{2}}{4}$","$-\\dfrac{\\sqrt{6} - \\sqrt{2}}{4}$"]'::jsonb, 0, '$\cos 165^{\circ} = -\cos 15^{\circ}$ and $\cos 15^{\circ} = \cos(45^{\circ} - 30^{\circ}) = \dfrac{\sqrt{6} + \sqrt{2}}{4}$.', 'Compound Angles'),
  ('The exact value of $\sin 75^{\circ}$ is:', '["$\\dfrac{\\sqrt{6} - \\sqrt{2}}{4}$","$\\dfrac{\\sqrt{6} + \\sqrt{2}}{4}$","$\\dfrac{\\sqrt{3} + 1}{4}$","$\\dfrac{1}{4}$"]'::jsonb, 1, '$\sin(45^{\circ} + 30^{\circ}) = \tfrac{\sqrt{2}}{2}\cdot\tfrac{\sqrt{3}}{2} + \tfrac{\sqrt{2}}{2}\cdot\tfrac{1}{2} = \tfrac{\sqrt{6} + \sqrt{2}}{4} \approx 0.9659$.', 'Compound Angles'),
  ('For an acute angle $\theta$, $\cot\!\left(\dfrac{\pi}{2} + \theta\right)$ equals:', '["$-\\sin\\theta$","$\\cos\\theta$","$-\\tan\\theta$","$-\\cot\\theta$"]'::jsonb, 2, 'In the second quadrant $\cot$ is negative, and $\cot(\tfrac{\pi}{2} + \theta) = -\tan\theta$.', 'Allied Angles'),
  ('A solution of $\sin x - 2\sin x\cos x = 0$ in the interval $0 < x < \pi$ is:', '["$0$","$\\pi$","$\\dfrac{5\\pi}{3}$","$\\dfrac{\\pi}{3}$"]'::jsonb, 3, '$\sin x(1 - 2\cos x) = 0$. In $(0, \pi)$, $\sin x \neq 0$, so $\cos x = \tfrac{1}{2}$ and $x = \tfrac{\pi}{3}$.', 'Trigonometric Equations'),
  ('The identity $1 + \tan^{2}\theta$ equals:', '["$\\sec^{2}\\theta$","$\\csc^{2}\\theta$","$\\cot^{2}\\theta$","$\\sin^{2}\\theta$"]'::jsonb, 0, 'Dividing $\sin^{2}\theta + \cos^{2}\theta = 1$ by $\cos^{2}\theta$ gives $\tan^{2}\theta + 1 = \sec^{2}\theta$.', 'Trigonometric Identities'),
  ('The identity $1 + \cot^{2}\theta$ equals:', '["$\\sec^{2}\\theta$","$\\csc^{2}\\theta$","$\\tan^{2}\\theta$","$\\cos^{2}\\theta$"]'::jsonb, 1, 'Dividing $\sin^{2}\theta + \cos^{2}\theta = 1$ by $\sin^{2}\theta$.', 'Trigonometric Identities'),
  ('$\sin(-\theta)$ equals:', '["$\\sin\\theta$","$\\cos\\theta$","$-\\sin\\theta$","$-\\cos\\theta$"]'::jsonb, 2, 'Sine is an odd function, while cosine is even.', 'Trigonometric Identities'),
  ('$\cos 2\theta$ can be written as:', '["$2\\sin\\theta\\cos\\theta$","$1 + 2\\sin^{2}\\theta$","$\\sin^{2}\\theta - \\cos^{2}\\theta$","$1 - 2\\sin^{2}\\theta$"]'::jsonb, 3, '$\cos 2\theta = \cos^{2}\theta - \sin^{2}\theta = 1 - 2\sin^{2}\theta = 2\cos^{2}\theta - 1$.', 'Double Angle Formulas'),
  ('Solve for $z$: $2z + \bar{z} = 3 - 2i$.', '["$1 - 2i$","$-1 + 2i$","$1 + 2i$","$-1 - 2i$"]'::jsonb, 0, 'Let $z = a + bi$. Then $2z + \bar{z} = 3a + bi = 3 - 2i$, so $a = 1$ and $b = -2$.', 'Complex Numbers'),
  ('Express $(1 + 3i)(1 - 2i)$ in the form $a + bi$.', '["-5 + 5i","7 + 1i","7 - i","1 + i"]'::jsonb, 1, '$(1 + 3i)(1 - 2i) = 1 - 2i + 3i - 6i^{2} = 7 + i$.', 'Complex Numbers'),
  ('The modulus of $(1 + 3i)(1 - 2i) = 7 + i$ is:', '["$\\sqrt{26}$","$\\sqrt{8}$","$\\sqrt{50}$","$7$"]'::jsonb, 2, '$|7 + i| = \sqrt{49 + 1} = \sqrt{50}$.', 'Complex Numbers'),
  ('The principal argument of $i^{2}$ is:', '["$\\dfrac{\\pi}{2}$","$-\\dfrac{\\pi}{2}$","$-\\pi$","$\\pi$"]'::jsonb, 3, '$i^{2} = -1$, which lies on the negative real axis, so $\arg = \pi$ (principal value in $(-\pi, \pi]$).', 'Complex Numbers'),
  ('The principal argument of $z = -\dfrac{8}{25}i$ is:', '["$-\\dfrac{\\pi}{2}$","$\\dfrac{\\pi}{2}$","$\\pi$","$-\\dfrac{3\\pi}{2}$"]'::jsonb, 0, '$z$ lies on the negative imaginary axis, so $\arg z = -\tfrac{\pi}{2}$.', 'Complex Numbers'),
  ('One of the cube roots of $1 + i$ is:', '["$3\\left[\\cos\\dfrac{\\pi}{4} + i\\sin\\dfrac{\\pi}{4}\\right]$","$2^{1/6}\\left[\\cos\\dfrac{\\pi}{12} + i\\sin\\dfrac{\\pi}{12}\\right]$","$\\cos\\dfrac{\\pi}{4} + i\\sin\\dfrac{\\pi}{4}$","$2\\left[\\cos\\dfrac{\\pi}{3} + i\\sin\\dfrac{\\pi}{3}\\right]$"]'::jsonb, 1, '$1 + i = \sqrt{2}\,(\cos\tfrac{\pi}{4} + i\sin\tfrac{\pi}{4})$. By De Moivre, a cube root has modulus $(\sqrt{2})^{1/3} = 2^{1/6}$ and argument $\tfrac{\pi}{12}$.', 'De Moivre''s Theorem'),
  ('The first three terms in the expansion of $(1 - 2y)^{-3}$ in ascending powers of $y$ are:', '["$1 - 6y + 24y^{2}$","$1 + 6y + 12y^{2}$","$1 + 6y + 24y^{2}$","$1 + 3y + 6y^{2}$"]'::jsonb, 2, '$(1 + u)^{-3} = 1 - 3u + 6u^{2} - \dots$ with $u = -2y$ gives $1 + 6y + 24y^{2}$.', 'Binomial Theorem'),
  ('The coefficient of $t^{2}$ in the expansion of $(9 - 6t)^{-3/2}$ is:', '["$\\dfrac{5}{6}$","$\\dfrac{162}{5}$","$-\\dfrac{5}{162}$","$\\dfrac{5}{162}$"]'::jsonb, 3, '$(9 - 6t)^{-3/2} = \dfrac{1}{27}\left(1 - \dfrac{2t}{3}\right)^{-3/2}$. The $t^{2}$ coefficient of the bracket is $\dfrac{(-3/2)(-5/2)}{2}\cdot\dfrac{4}{9} = \dfrac{5}{6}$, so the answer is $\dfrac{5}{6\times27} = \dfrac{5}{162}$ (0.03086).', 'Binomial Theorem')
),
tgt as (
  select subject_id, subject_name, faculty, department, level, semester, units
    from public.cbt_questions
   where subject_name ilike 'MTH 101%' and subject_id not like '%coming-soon'
   limit 1
)
insert into public.cbt_questions
  (subject_id, subject_name, institution, faculty, department, level,
   question, options, correct_index, explanation, topic, is_general, semester, units)
select coalesce(t.subject_id, 'mth-101-elementary-mathematics-1'),
       coalesce(t.subject_name, 'MTH 101: Elementary Mathematics I'),
       'University of Nigeria, Nsukka',
       coalesce(t.faculty, 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences, Faculty of Education'),
       coalesce(t.department, 'Mathematics'),
       coalesce(t.level, '100 Level'),
       s.question, s.options, s.correct_index, s.explanation, s.topic, false,
       coalesce(t.semester, 'first'),
       coalesce(t.units, 2)
  from src s
  left join tgt t on true
 where not exists (
   select 1 from public.cbt_questions c
    where c.subject_id = coalesce(t.subject_id, 'mth-101-elementary-mathematics-1') and c.question = s.question);

select subject_id, subject_name, count(*) as questions
  from public.cbt_questions
 where subject_name ilike 'MTH 101%' and subject_id not like '%coming-soon'
 group by 1, 2;


-- ============ PART 2: unn_mth101_ca_workbook_cbt_questions.sql ============
-- MTH 101: questions from the MTH 101 CA workbook (Chapter 2)
-- =============================================================================
-- 20 questions built from the CA exercises (induction, quadratics, progressions,
-- binomial theorem, polynomials, inequalities, counting, radical equations,
-- trigonometry, complex numbers). Every question was re-solved; the handwritten
-- solutions in the scan were NOT trusted. Corrections: tan(A + B) with B obtuse is
-- -33/56 (the scan used a positive cosine); 2x^2 - 3x - 2 < 0 is -1/2 < x < 2;
-- the GP sum was recomputed exactly. The 3-set question (whose data give a non-
-- whole-number answer, 5/3) and the garbled logarithm/exponential items were dropped.
-- ADDS ONLY to the existing MTH 101 paper; repeats are skipped.
-- =============================================================================
with src (question, options, correct_index, explanation, topic) as (
values
  ('If $\alpha$ and $\beta$ are the roots of $2x^{2} - 5x - 3 = 0$, the equation with integer coefficients whose roots are $\dfrac{1}{\alpha}$ and $\dfrac{1}{\beta}$ is:', '["$3x^{2} + 5x - 2 = 0$","$3x^{2} - 5x - 2 = 0$","$2x^{2} + 5x - 3 = 0$","$3x^{2} + 5x + 2 = 0$"]'::jsonb, 0, 'Replacing $x$ by $1/x$ in $2x^{2} - 5x - 3 = 0$ and clearing fractions gives $2 - 5x - 3x^{2} = 0$, i.e. $3x^{2} + 5x - 2 = 0$. (Check: $\tfrac{1}{\alpha} + \tfrac{1}{\beta} = \tfrac{\alpha + \beta}{\alpha\beta} = \tfrac{5/2}{-3/2} = -\tfrac{5}{3}$.)', 'Theory of Quadratic Equations'),
  ('If $\alpha$ and $\beta$ are the roots of $2x^{2} - 5x - 3 = 0$, the equation with integer coefficients whose roots are $\alpha + 1$ and $\beta + 1$ is:', '["$2x^{2} + 9x + 4 = 0$","$2x^{2} - 9x + 4 = 0$","$2x^{2} - 5x + 4 = 0$","$x^{2} - 9x + 4 = 0$"]'::jsonb, 1, '$\alpha + \beta = \tfrac{5}{2}$ and $\alpha\beta = -\tfrac{3}{2}$. New sum $= \tfrac{5}{2} + 2 = \tfrac{9}{2}$; new product $= \alpha\beta + (\alpha + \beta) + 1 = 2$. Equation: $x^{2} - \tfrac{9}{2}x + 2 = 0$, i.e. $2x^{2} - 9x + 4 = 0$.', 'Theory of Quadratic Equations'),
  ('The numbers $x$, $2x - 1$ and $5x + 1$ are three consecutive terms of an arithmetic progression. The value of $x$ is:', '["$\\dfrac{3}{2}$","$-2$","$-\\dfrac{3}{2}$","$2$"]'::jsonb, 2, 'Equal differences: $(2x - 1) - x = (5x + 1) - (2x - 1)$ gives $x - 1 = 3x + 2$, so $x = -\tfrac{3}{2}$.', 'Arithmetic Progression'),
  ('For the progression with consecutive terms $x$, $2x - 1$, $5x + 1$ (where $x = -\tfrac{3}{2}$), the 23rd term is:', '["-55","-58","-59.5","-56.5"]'::jsonb, 3, 'The first term is $-1.5$ and the common difference is $-2.5$. $T_{23} = a + 22d = -1.5 + 22(-2.5) = -56.5$.', 'Arithmetic Progression'),
  ('The sum to infinity of the geometric series $6 + 3 + \tfrac{3}{2} + \tfrac{3}{4} + \dots$ is:', '["12","9","6","18"]'::jsonb, 0, '$a = 6$, $r = \tfrac{1}{2}$, so $S_{\infty} = \dfrac{6}{1 - 1/2} = 12$.', 'Geometric Progression'),
  ('The 6th term of a geometric progression with positive terms is 72 and the 8th term is 288. The common ratio is:', '["4","2","3","$\\sqrt{2}$"]'::jsonb, 1, '$\dfrac{T_{8}}{T_{6}} = r^{2} = 4$, so $r = 2$.', 'Geometric Progression'),
  ('For that progression ($T_{6} = 72$, $r = 2$), the sum of the first 5 terms is:', '["72","62","69.75","93"]'::jsonb, 2, '$a = \dfrac{72}{2^{5}} = 2.25$. $S_{5} = a\,\dfrac{2^{5} - 1}{2 - 1} = 2.25 \times 31 = 69.75$.', 'Geometric Progression'),
  ('The coefficient of $(xy)^{5}$ in the expansion of $\left(x + \dfrac{y}{4}\right)^{10}$ is:', '["$\\dfrac{63}{1024}$","$\\dfrac{252}{4}$","$\\dfrac{63}{128}$","$\\dfrac{63}{256}$"]'::jsonb, 3, 'The term is $\binom{10}{5}x^{5}\left(\dfrac{y}{4}\right)^{5} = \dfrac{252}{1024}x^{5}y^{5} = \dfrac{63}{256}(xy)^{5}$.', 'Binomial Theorem'),
  ('When the polynomial $f(x) = x^{3} + 3x^{2} + ax - 2$ is divided by $x - 3$ the remainder is 100. The value of $a$ is:', '["16","12","18","14"]'::jsonb, 0, '$f(3) = 27 + 27 + 3a - 2 = 52 + 3a = 100$, so $a = 16$.', 'Remainder Theorem'),
  ('The binomial expansion of $(1 + x)^{n}$, with $n$ not a positive integer, is valid for:', '["$|x| > 1$","$|x| < 1$","all real values of $x$","$x > 0$ only"]'::jsonb, 1, 'The infinite series converges only when $-1 < x < 1$. For a positive integer $n$ the expansion is finite and holds for every $x$.', 'Binomial Theorem'),
  ('The solution of the inequality $2x^{2} - 3x - 2 < 0$ is:', '["$x < -\\dfrac{1}{2}$ or $x > 2$","$x < 2$","$-\\dfrac{1}{2} < x < 2$","$-2 < x < \\dfrac{1}{2}$"]'::jsonb, 2, '$2x^{2} - 3x - 2 = (2x + 1)(x - 2)$, which is negative between the roots $-\tfrac{1}{2}$ and $2$.', 'Quadratic Inequalities'),
  ('In how many ways can a committee of 2 men and 2 women be formed from 3 men and 5 women?', '["60","15","45","30"]'::jsonb, 3, '${}^{3}C_{2} \times {}^{5}C_{2} = 3 \times 10 = 30$.', 'Combinations'),
  ('Solve $\sqrt{2x + 3} - \sqrt{x - 2} = 2$.', '["$x = 3$ or $x = 11$","$x = 3$ only","$x = 11$ only","$x = 2$ or $x = 14$"]'::jsonb, 0, 'Write $\sqrt{2x + 3} = 2 + \sqrt{x - 2}$ and square: $x + 1 = 4\sqrt{x - 2}$. Squaring again: $x^{2} - 14x + 33 = 0$, so $x = 3$ or $x = 11$. Both satisfy the original equation (3: $3 - 1 = 2$; 11: $5 - 3 = 2$).', 'Radical Equations'),
  ('Simplify $(\sin\theta + \cos\theta)^{2} + (\sin\theta - \cos\theta)^{2}$.', '["1","2","$2\\sin\\theta\\cos\\theta$","0"]'::jsonb, 1, 'Expanding: $2\sin^{2}\theta + 2\cos^{2}\theta = 2$.', 'Trigonometric Identities'),
  ('Solve $\cos 2\theta + 1 = \cos\theta$ for $0 \leq \theta < 2\pi$.', '["$\\theta = 0,\\ \\dfrac{\\pi}{3},\\ \\dfrac{5\\pi}{3}$","$\\theta = \\dfrac{\\pi}{2},\\ \\dfrac{3\\pi}{2}$ only","$\\theta = \\dfrac{\\pi}{3},\\ \\dfrac{\\pi}{2},\\ \\dfrac{3\\pi}{2},\\ \\dfrac{5\\pi}{3}$","$\\theta = \\dfrac{\\pi}{6},\\ \\dfrac{5\\pi}{6},\\ \\dfrac{7\\pi}{6},\\ \\dfrac{11\\pi}{6}$"]'::jsonb, 2, '$\cos 2\theta + 1 = 2\cos^{2}\theta$, so $2\cos^{2}\theta = \cos\theta$ and $\cos\theta(2\cos\theta - 1) = 0$. Hence $\cos\theta = 0$ or $\tfrac{1}{2}$: $\theta = \tfrac{\pi}{2}, \tfrac{3\pi}{2}, \tfrac{\pi}{3}, \tfrac{5\pi}{3}$.', 'Trigonometric Equations'),
  ('If $\cos A = \dfrac{4}{5}$ and $\sin B = \dfrac{12}{13}$, with $A$ acute and $B$ obtuse, then $\tan(A + B)$ equals:', '["$\\dfrac{33}{56}$","$\\dfrac{63}{16}$","$-\\dfrac{16}{63}$","$-\\dfrac{33}{56}$"]'::jsonb, 3, '$\tan A = \tfrac{3}{4}$. For obtuse $B$, $\cos B = -\tfrac{5}{13}$, so $\tan B = -\tfrac{12}{5}$. Then $\tan(A + B) = \dfrac{\tfrac{3}{4} - \tfrac{12}{5}}{1 + \tfrac{3}{4}\cdot\tfrac{12}{5}} = \dfrac{-33/20}{14/5} = -\dfrac{33}{56}$.', 'Compound Angles'),
  ('If $z = \dfrac{1}{1 + i}$, then $z$ in the form $x + iy$ is:', '["$\\dfrac{1}{2} - \\dfrac{1}{2}i$","$\\dfrac{1}{2} + \\dfrac{1}{2}i$","$1 - i$","$-\\dfrac{1}{2} - \\dfrac{1}{2}i$"]'::jsonb, 0, 'Multiply by the conjugate: $\dfrac{1 - i}{(1 + i)(1 - i)} = \dfrac{1 - i}{2}$.', 'Complex Numbers'),
  ('The principal argument of $z = \dfrac{1}{25i}$ is:', '["$\\dfrac{\\pi}{2}$","$-\\dfrac{\\pi}{2}$","$\\pi$","$0$"]'::jsonb, 1, '$\dfrac{1}{25i} = -\dfrac{i}{25}$, which lies on the negative imaginary axis, so $\operatorname{Arg} z = -\tfrac{\pi}{2}$ (and $\arg z = -\tfrac{\pi}{2} + 2k\pi$).', 'Complex Numbers'),
  ('The principal argument of $z = \dfrac{1}{1 - 3i}$ is:', '["$-\\tan^{-1}3$","$\\tan^{-1}\\dfrac{1}{3}$","$\\tan^{-1}3$","$\\dfrac{\\pi}{2}$"]'::jsonb, 2, '$z = \dfrac{1 + 3i}{10}$ lies in the first quadrant, so $\operatorname{Arg} z = \tan^{-1}\dfrac{3/10}{1/10} = \tan^{-1}3 \approx 1.249$ rad.', 'Complex Numbers'),
  ('The value of $\left(1 + \dfrac{1}{i}\right)^{8}$ is:', '["-16","$16i$","256","16"]'::jsonb, 3, '$1 + \tfrac{1}{i} = 1 - i = \sqrt{2}\,(\cos\tfrac{\pi}{4} - i\sin\tfrac{\pi}{4})$. By De Moivre, the 8th power has modulus $(\sqrt{2})^{8} = 16$ and argument $-2\pi$, so the value is $16$.', 'De Moivre''s Theorem')
),
tgt as (
  select subject_id, subject_name, faculty, department, level, semester, units
    from public.cbt_questions
   where subject_name ilike 'MTH 101%' and subject_id not like '%coming-soon'
   limit 1
)
insert into public.cbt_questions
  (subject_id, subject_name, institution, faculty, department, level,
   question, options, correct_index, explanation, topic, is_general, semester, units)
select coalesce(t.subject_id, 'mth-101-elementary-mathematics-1'),
       coalesce(t.subject_name, 'MTH 101: Elementary Mathematics I'),
       'University of Nigeria, Nsukka',
       coalesce(t.faculty, 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences, Faculty of Education'),
       coalesce(t.department, 'Mathematics'),
       coalesce(t.level, '100 Level'),
       s.question, s.options, s.correct_index, s.explanation, s.topic, false,
       coalesce(t.semester, 'first'),
       coalesce(t.units, 2)
  from src s
  left join tgt t on true
 where not exists (
   select 1 from public.cbt_questions c
    where c.subject_id = coalesce(t.subject_id, 'mth-101-elementary-mathematics-1') and c.question = s.question);

select subject_id, subject_name, count(*) as questions
  from public.cbt_questions
 where subject_name ilike 'MTH 101%' and subject_id not like '%coming-soon'
 group by 1, 2;


-- ============ PART 3: unn_mth102_additional_cbt_questions.sql ============
-- MTH 102: Elementary Mathematics (coordinate geometry and vectors) -- additional questions
-- (old code MTH 122)
-- =============================================================================
-- 98 original questions with computed answers on the straight line, circle, parabola,
-- ellipse, hyperbola, classification of conics and vectors (dot and cross product,
-- direction cosines, linear dependence, triple product), including the exercises on the
-- MTH 102 assignment sheet. They use different numbers from the questions the app already
-- has (about 470 for MTH 102 / MTH 122). The booklets and the Amazigo textbook were
-- used only to confirm the topic list; nothing was copied.
-- ADDS ONLY: joins the existing MTH 102 paper; repeats are skipped.
-- =============================================================================
with src (question, options, correct_index, explanation, topic) as (
values
  ('Find the distance between the points $A(-2, 5)$ and $B(3, -7)$.', '["$13$","$\\sqrt{173}$","$4\\sqrt{10}$","$13\\sqrt{2}$"]'::jsonb, 0, '$|AB| = \sqrt{(3 - (-2))^{2} + (-7 - 5)^{2}} = \sqrt{169} = 13$.', 'Straight Line'),
  ('Find the distance between the points $A(1, 2)$ and $B(7, 10)$.', '["$2\\sqrt{26}$","$10$","$\\sqrt{91}$","$10\\sqrt{2}$"]'::jsonb, 1, '$|AB| = \sqrt{(7 - 1)^{2} + (10 - 2)^{2}} = \sqrt{100} = 10$.', 'Straight Line'),
  ('Find the distance between the points $A(-4, -1)$ and $B(2, 7)$.', '["$2\\sqrt{26}$","$\\sqrt{91}$","$10$","$10\\sqrt{2}$"]'::jsonb, 2, '$|AB| = \sqrt{(2 - (-4))^{2} + (7 - (-1))^{2}} = \sqrt{100} = 10$.', 'Straight Line'),
  ('Find the distance between the points $A(0, 0)$ and $B(5, 12)$.', '["$\\sqrt{173}$","$4\\sqrt{10}$","$13\\sqrt{2}$","$13$"]'::jsonb, 3, '$|AB| = \sqrt{(5 - 0)^{2} + (12 - 0)^{2}} = \sqrt{169} = 13$.', 'Straight Line'),
  ('Find the distance between the points $A(3, -4)$ and $B(-5, 2)$.', '["$10$","$2\\sqrt{26}$","$\\sqrt{91}$","$10\\sqrt{2}$"]'::jsonb, 0, '$|AB| = \sqrt{(-5 - 3)^{2} + (2 - (-4))^{2}} = \sqrt{100} = 10$.', 'Straight Line'),
  ('The point $P$ divides the line joining $A(1, 2)$ and $B(7, 14)$ internally in the ratio $1 : 2$. The coordinates of $P$ are:', '["$(5, 10)$","$(3, 6)$","$(4, 8)$","$(4, 5)$"]'::jsonb, 1, '$P = \left(\dfrac{1x_{2} + 2x_{1}}{3}, \dfrac{1y_{2} + 2y_{1}}{3}\right) = (3, 6)$.', 'Division of a Line Segment'),
  ('The point $P$ divides the line joining $A(-3, 4)$ and $B(6, -2)$ internally in the ratio $2 : 1$. The coordinates of $P$ are:', '["$(0, 2)$","$(\\dfrac{5}{3}, 1)$","$(3, 0)$","$(4, -1)$"]'::jsonb, 2, '$P = \left(\dfrac{2x_{2} + 1x_{1}}{3}, \dfrac{2y_{2} + 1y_{1}}{3}\right) = (3, 0)$.', 'Division of a Line Segment'),
  ('The point $P$ divides the line joining $A(0, 1)$ and $B(10, 6)$ internally in the ratio $3 : 2$. The coordinates of $P$ are:', '["$(4, 3)$","$(5, \\dfrac{18}{5})$","$(7, 3)$","$(6, 4)$"]'::jsonb, 3, '$P = \left(\dfrac{3x_{2} + 2x_{1}}{5}, \dfrac{3y_{2} + 2y_{1}}{5}\right) = (6, 4)$.', 'Division of a Line Segment'),
  ('The point $P$ divides the line joining $A(2, -5)$ and $B(-4, 7)$ internally in the ratio $1 : 3$. The coordinates of $P$ are:', '["$(\\dfrac{1}{2}, -2)$","$(\\dfrac{-5}{2}, 4)$","$(-1, 1)$","$(\\dfrac{3}{2}, -3)$"]'::jsonb, 0, '$P = \left(\dfrac{1x_{2} + 3x_{1}}{4}, \dfrac{1y_{2} + 3y_{1}}{4}\right) = (\dfrac{1}{2}, -2)$.', 'Division of a Line Segment'),
  ('Find the area of the triangle with vertices $A(0, 0)$, $B(6, 0)$ and $C(0, 8)$.', '["$25$","$24$","$23$","$48$"]'::jsonb, 1, 'Area $= \tfrac{1}{2}|x_{1}(y_{2} - y_{3}) + x_{2}(y_{3} - y_{1}) + x_{3}(y_{1} - y_{2})| = 24$ square units.', 'Area of a Triangle'),
  ('Find the area of the triangle with vertices $A(1, 1)$, $B(5, 1)$ and $C(3, 7)$.', '["$13$","$11$","$12$","$24$"]'::jsonb, 2, 'Area $= \tfrac{1}{2}|x_{1}(y_{2} - y_{3}) + x_{2}(y_{3} - y_{1}) + x_{3}(y_{1} - y_{2})| = 12$ square units.', 'Area of a Triangle'),
  ('Find the area of the triangle with vertices $A(-2, 3)$, $B(4, -1)$ and $C(6, 5)$.', '["$23$","$21$","$44$","$22$"]'::jsonb, 3, 'Area $= \tfrac{1}{2}|x_{1}(y_{2} - y_{3}) + x_{2}(y_{3} - y_{1}) + x_{3}(y_{1} - y_{2})| = 22$ square units.', 'Area of a Triangle'),
  ('Find the area of the triangle with vertices $A(2, 2)$, $B(8, 4)$ and $C(5, 9)$.', '["$18$","$19$","$17$","$36$"]'::jsonb, 0, 'Area $= \tfrac{1}{2}|x_{1}(y_{2} - y_{3}) + x_{2}(y_{3} - y_{1}) + x_{3}(y_{1} - y_{2})| = 18$ square units.', 'Area of a Triangle'),
  ('Find the equation of the line through $A(1, 2)$ and $B(4, 8)$.', '["$2x+y=0$","$2x-y=0$","$x-2y=0$","$6x-3y+1=0$"]'::jsonb, 1, 'Gradient $m = \dfrac{8 - 2}{4 - 1} = 2$. Using $y - y_{1} = m(x - x_{1})$ and simplifying gives $2x-y=0$.', 'Equation of a Straight Line'),
  ('Find the equation of the line through $A(-1, 3)$ and $B(5, 6)$.', '["$x-2y-7=0$","$x+2y+7=0$","$x-2y+7=0$","$2x-y-7=0$"]'::jsonb, 2, 'Gradient $m = \dfrac{6 - 3}{5 - (-1)} = \dfrac{1}{2}$. Using $y - y_{1} = m(x - x_{1})$ and simplifying gives $x-2y+7=0$.', 'Equation of a Straight Line'),
  ('Find the equation of the line through $A(2, -3)$ and $B(6, 5)$.', '["$2x-y+7=0$","$2x+y-7=0$","$x-2y+7=0$","$2x-y-7=0$"]'::jsonb, 3, 'Gradient $m = \dfrac{5 - (-3)}{6 - 2} = 2$. Using $y - y_{1} = m(x - x_{1})$ and simplifying gives $2x-y-7=0$.', 'Equation of a Straight Line'),
  ('Find the equation of the line through $A(0, 4)$ and $B(3, 0)$.', '["$4x+3y-12=0$","$4x+3y+12=0$","$4x-3y-12=0$","$3x+4y-12=0$"]'::jsonb, 0, 'Gradient $m = \dfrac{0 - 4}{3 - 0} = \dfrac{-4}{3}$. Using $y - y_{1} = m(x - x_{1})$ and simplifying gives $4x+3y-12=0$.', 'Equation of a Straight Line'),
  ('Find the acute angle between the lines with gradients $2$ and $-\tfrac{1}{3}$.', '["$97^{\\circ}$","$112^{\\circ}$","$81.87^{\\circ}$","$8^{\\circ}$"]'::jsonb, 2, '$\tan\theta = \left|\dfrac{m_{1} - m_{2}}{1 + m_{1}m_{2}}\right| = 7$, so $\theta = 81.87^{\circ}$.', 'Angle Between Two Lines'),
  ('Find the acute angle between the lines with gradients $1$ and $\tfrac{1}{2}$.', '["$33^{\\circ}$","$48^{\\circ}$","$72^{\\circ}$","$18.43^{\\circ}$"]'::jsonb, 3, '$\tan\theta = \left|\dfrac{m_{1} - m_{2}}{1 + m_{1}m_{2}}\right| = 0.333$, so $\theta = 18.43^{\circ}$.', 'Angle Between Two Lines'),
  ('The lines $2x + ky = 7$ and $3x - 6y = 1$ are perpendicular. The value of $k$ is:', '["$1$","$-1$","$4$","$-4$"]'::jsonb, 0, 'Gradients: $m_{1} = -\dfrac{2}{k}$ and $m_{2} = \dfrac{3}{6} = \dfrac{1}{2}$. Perpendicular means $m_{1}m_{2} = -1$: $-\dfrac{1}{k} = -1$, so $k = 1$.', 'Parallel and Perpendicular Lines'),
  ('The lines $kx + 3y = 4$ and $4x + 6y = 9$ are parallel. The value of $k$ is:', '["$4$","$2$","$-2$","$\\dfrac{9}{2}$"]'::jsonb, 1, 'Parallel lines have equal gradients: $-\dfrac{k}{3} = -\dfrac{4}{6}$, so $k = 2$.', 'Parallel and Perpendicular Lines'),
  ('The line through $(1, 2)$ perpendicular to $y = 4x - 1$ has gradient:', '["$4$","$\\dfrac{1}{4}$","$-\\dfrac{1}{4}$","$-4$"]'::jsonb, 2, 'Perpendicular gradients multiply to $-1$, so $m = -\tfrac{1}{4}$.', 'Parallel and Perpendicular Lines'),
  ('Find the perpendicular distance of the point $(6, 4)$ from the line $3x+4y-10=0$.', '["$5.8$","$3.8$","$9.6$","$4.8$"]'::jsonb, 3, '$d = \dfrac{|ax_{1} + by_{1} + c|}{\sqrt{a^{2} + b^{2}}} = \dfrac{|3(6) + 4(4) + -10|}{\sqrt{25}} = 4.8$.', 'Distance of a Point from a Line'),
  ('Find the perpendicular distance of the point $(0, 0)$ from the line $5x+12y-13=0$.', '["$1$","$2$","$0$","$0.5$"]'::jsonb, 0, '$d = \dfrac{|ax_{1} + by_{1} + c|}{\sqrt{a^{2} + b^{2}}} = \dfrac{|5(0) + 12(0) + -13|}{\sqrt{169}} = 1$.', 'Distance of a Point from a Line'),
  ('Find the perpendicular distance of the point $(0, 0)$ from the line $3x-4y+5=0$.', '["$2$","$1$","$0$","$0.5$"]'::jsonb, 1, '$d = \dfrac{|ax_{1} + by_{1} + c|}{\sqrt{a^{2} + b^{2}}} = \dfrac{|3(0) + -4(0) + 5|}{\sqrt{25}} = 1$.', 'Distance of a Point from a Line'),
  ('Find the perpendicular distance of the point $(2, 3)$ from the line $6x+8y-9=0$.', '["$3.7$","$1.7$","$2.7$","$5.4$"]'::jsonb, 2, '$d = \dfrac{|ax_{1} + by_{1} + c|}{\sqrt{a^{2} + b^{2}}} = \dfrac{|6(2) + 8(3) + -9|}{\sqrt{100}} = 2.7$.', 'Distance of a Point from a Line'),
  ('Find the point of intersection of the lines $x+y-5=0$ and $x-y-1=0$.', '["$(2, 3)$","$(-3, 2)$","$(3, -2)$","$(3, 2)$"]'::jsonb, 3, 'Solving the two equations simultaneously gives $x = 3$ and $y = 2$.', 'Intersection of Lines'),
  ('Find the point of intersection of the lines $2x+y-8=0$ and $x-y+1=0$.', '["$(\\dfrac{7}{3}, \\dfrac{10}{3})$","$(\\dfrac{10}{3}, \\dfrac{7}{3})$","$(\\dfrac{-7}{3}, \\dfrac{10}{3})$","$(\\dfrac{7}{3}, \\dfrac{-10}{3})$"]'::jsonb, 0, 'Solving the two equations simultaneously gives $x = \dfrac{7}{3}$ and $y = \dfrac{10}{3}$.', 'Intersection of Lines'),
  ('Find the point of intersection of the lines $3x-2y-4=0$ and $x+y-6=0$.', '["$(\\dfrac{14}{5}, \\dfrac{16}{5})$","$(\\dfrac{16}{5}, \\dfrac{14}{5})$","$(\\dfrac{-16}{5}, \\dfrac{14}{5})$","$(\\dfrac{16}{5}, \\dfrac{-14}{5})$"]'::jsonb, 1, 'Solving the two equations simultaneously gives $x = \dfrac{16}{5}$ and $y = \dfrac{14}{5}$.', 'Intersection of Lines'),
  ('The circle $x^{2} + y^{2} - 4x + 6y - 12 = 0$ has centre and radius:', '["$(-2, 3),\\ r = 5$","$(2, -3),\\ r = 25$","$(2, -3),\\ r = 5$","$(-3, 2),\\ r = 5$"]'::jsonb, 2, 'Complete the square: centre $(-\tfrac{D}{2}, -\tfrac{E}{2}) = (2, -3)$ and $r = \sqrt{\tfrac{D^{2} + E^{2}}{4} - F} = 5$.', 'Equation of a Circle'),
  ('The circle $x^{2} + y^{2} + 2x - 8y + 8 = 0$ has centre and radius:', '["$(1, -4),\\ r = 3$","$(-1, 4),\\ r = 9$","$(4, -1),\\ r = 3$","$(-1, 4),\\ r = 3$"]'::jsonb, 3, 'Complete the square: centre $(-\tfrac{D}{2}, -\tfrac{E}{2}) = (-1, 4)$ and $r = \sqrt{\tfrac{D^{2} + E^{2}}{4} - F} = 3$.', 'Equation of a Circle'),
  ('The circle $x^{2} + y^{2} - 4y - 45 = 0$ has centre and radius:', '["$(0, 2),\\ r = 7$","$(0, -2),\\ r = 7$","$(0, 2),\\ r = 49$","$(2, 0),\\ r = 7$"]'::jsonb, 0, 'Complete the square: centre $(-\tfrac{D}{2}, -\tfrac{E}{2}) = (0, 2)$ and $r = \sqrt{\tfrac{D^{2} + E^{2}}{4} - F} = 7$.', 'Equation of a Circle'),
  ('The circle $x^{2} + y^{2} - 6x - 2y - 6 = 0$ has centre and radius:', '["$(-3, -1),\\ r = 4$","$(3, 1),\\ r = 4$","$(3, 1),\\ r = 16$","$(1, 3),\\ r = 4$"]'::jsonb, 1, 'Complete the square: centre $(-\tfrac{D}{2}, -\tfrac{E}{2}) = (3, 1)$ and $r = \sqrt{\tfrac{D^{2} + E^{2}}{4} - F} = 4$.', 'Equation of a Circle'),
  ('The points $A(1, 2)$ and $B(5, 6)$ are the ends of a diameter of a circle. The centre of the circle is:', '["$(1, 2)$","$(4, 4)$","$(3, 4)$","$(2, 2)$"]'::jsonb, 2, 'The centre is the midpoint of the diameter: $\left(\dfrac{1 + 5}{2}, \dfrac{2 + 6}{2}\right) = (3, 4)$.', 'Equation of a Circle'),
  ('For the circle with diameter ends $A(1, 2)$ and $B(5, 6)$, the radius squared is:', '["$9$","$7$","$16$","$8$"]'::jsonb, 3, '$r = \tfrac{1}{2}|AB|$, so $r^{2} = \tfrac{(5 - 1)^{2} + (6 - 2)^{2}}{4} = 8$.', 'Equation of a Circle'),
  ('The points $A(-2, 1)$ and $B(4, 5)$ are the ends of a diameter of a circle. The centre of the circle is:', '["$(1, 3)$","$(-2, 1)$","$(2, 3)$","$(3, 2)$"]'::jsonb, 0, 'The centre is the midpoint of the diameter: $\left(\dfrac{-2 + 4}{2}, \dfrac{1 + 5}{2}\right) = (1, 3)$.', 'Equation of a Circle'),
  ('For the circle with diameter ends $A(-2, 1)$ and $B(4, 5)$, the radius squared is:', '["$14$","$13$","$12$","$26$"]'::jsonb, 1, '$r = \tfrac{1}{2}|AB|$, so $r^{2} = \tfrac{(4 - (-2))^{2} + (5 - 1)^{2}}{4} = 13$.', 'Equation of a Circle'),
  ('For the circle with diameter ends $A(0, 0)$ and $B(6, 8)$, the radius squared is:', '["$26$","$24$","$50$","$25$"]'::jsonb, 3, '$r = \tfrac{1}{2}|AB|$, so $r^{2} = \tfrac{(6 - 0)^{2} + (8 - 0)^{2}}{4} = 25$.', 'Equation of a Circle'),
  ('Find the length of the tangent from the point $(5, 12)$ to the circle $x^{2} + y^{2} = 25$.', '["$12$","$3\\sqrt{17}$","$13$","$\\sqrt{133}$"]'::jsonb, 0, 'Length $= \sqrt{x_{1}^{2} + y_{1}^{2} - r^{2}} = \sqrt{25 + 144 - 25} = \sqrt{144} = 12$.', 'Tangents to a Circle'),
  ('Find the length of the tangent from the point $(10, 0)$ to the circle $x^{2} + y^{2} = 36$.', '["$\\sqrt{73}$","$8$","$10$","$\\sqrt{53}$"]'::jsonb, 1, 'Length $= \sqrt{x_{1}^{2} + y_{1}^{2} - r^{2}} = \sqrt{100 + 0 - 36} = \sqrt{64} = 8$.', 'Tangents to a Circle'),
  ('Find the length of the tangent from the point $(6, 8)$ to the circle $x^{2} + y^{2} = 64$.', '["$3\\sqrt{5}$","$10$","$6$","$5$"]'::jsonb, 2, 'Length $= \sqrt{x_{1}^{2} + y_{1}^{2} - r^{2}} = \sqrt{36 + 64 - 64} = \sqrt{36} = 6$.', 'Tangents to a Circle'),
  ('The tangent to the circle $x^{2} + y^{2} = 25$ at the point $(3, 4)$ on it is:', '["$4x + 3y = 25$","$3x - 4y = 25$","$3x + 4y = 12.5$","$3x + 4y = 25$"]'::jsonb, 3, 'For $x^{2} + y^{2} = r^{2}$ the tangent at $(x_{1}, y_{1})$ is $xx_{1} + yy_{1} = r^{2}$, i.e. $3x + 4y = 25$.', 'Tangents to a Circle'),
  ('The tangent to the circle $x^{2} + y^{2} = 169$ at the point $(5, 12)$ on it is:', '["$5x + 12y = 169$","$12x + 5y = 169$","$5x - 12y = 169$","$5x + 12y = 84.5$"]'::jsonb, 0, 'For $x^{2} + y^{2} = r^{2}$ the tangent at $(x_{1}, y_{1})$ is $xx_{1} + yy_{1} = r^{2}$, i.e. $5x + 12y = 169$.', 'Tangents to a Circle'),
  ('The tangent to the circle $x^{2} + y^{2} = 100$ at the point $(8, 6)$ on it is:', '["$6x + 8y = 100$","$8x + 6y = 100$","$8x - 6y = 100$","$8x + 6y = 50$"]'::jsonb, 1, 'For $x^{2} + y^{2} = r^{2}$ the tangent at $(x_{1}, y_{1})$ is $xx_{1} + yy_{1} = r^{2}$, i.e. $8x + 6y = 100$.', 'Tangents to a Circle'),
  ('The focus of the parabola $y^{2} = 12x$ is:', '["$(0, 3)$","$(-3, 0)$","$(3, 0)$","$(6, 0)$"]'::jsonb, 2, 'Compare with $y^{2} = 4ax$: $a = 3$, so the focus is $(3, 0)$.', 'Parabola'),
  ('The directrix of the parabola $y^{2} = 12x$ is:', '["$x = 3$","$y = -3$","$y = 3$","$x = -3$"]'::jsonb, 3, 'For $y^{2} = 4ax$ the directrix is $x = -a = -3$.', 'Parabola'),
  ('The focus of the parabola $y^{2} = 8x$ is:', '["$(2, 0)$","$(0, 2)$","$(-2, 0)$","$(4, 0)$"]'::jsonb, 0, 'Compare with $y^{2} = 4ax$: $a = 2$, so the focus is $(2, 0)$.', 'Parabola'),
  ('The directrix of the parabola $y^{2} = 8x$ is:', '["$x = 2$","$x = -2$","$y = -2$","$y = 2$"]'::jsonb, 1, 'For $y^{2} = 4ax$ the directrix is $x = -a = -2$.', 'Parabola'),
  ('The focus of the parabola $y^{2} = 20x$ is:', '["$(0, 5)$","$(-5, 0)$","$(5, 0)$","$(10, 0)$"]'::jsonb, 2, 'Compare with $y^{2} = 4ax$: $a = 5$, so the focus is $(5, 0)$.', 'Parabola'),
  ('The directrix of the parabola $y^{2} = 20x$ is:', '["$x = 5$","$y = -5$","$y = 5$","$x = -5$"]'::jsonb, 3, 'For $y^{2} = 4ax$ the directrix is $x = -a = -5$.', 'Parabola'),
  ('The focus of the parabola $y^{2} = 16x$ is:', '["$(4, 0)$","$(0, 4)$","$(-4, 0)$","$(8, 0)$"]'::jsonb, 0, 'Compare with $y^{2} = 4ax$: $a = 4$, so the focus is $(4, 0)$.', 'Parabola'),
  ('The directrix of the parabola $y^{2} = 16x$ is:', '["$x = 4$","$x = -4$","$y = -4$","$y = 4$"]'::jsonb, 1, 'For $y^{2} = 4ax$ the directrix is $x = -a = -4$.', 'Parabola'),
  ('The length of the latus rectum of the parabola $y^{2} = 12x$ is:', '["$6$","$3$","$12$","$24$"]'::jsonb, 2, 'The latus rectum of $y^{2} = 4ax$ has length $4a$.', 'Parabola'),
  ('The length of the latus rectum of the parabola $y^{2} = 8x$ is:', '["$4$","$2$","$16$","$8$"]'::jsonb, 3, 'The latus rectum of $y^{2} = 4ax$ has length $4a$.', 'Parabola'),
  ('The eccentricity of the ellipse $\dfrac{x^{2}}{25} + \dfrac{y^{2}}{9} = 1$ is:', '["$\\dfrac{4}{5}$","$\\dfrac{3}{5}$","$\\dfrac{5}{3}$","$\\dfrac{16}{25}$"]'::jsonb, 0, '$e = \sqrt{1 - \dfrac{b^{2}}{a^{2}}} = \sqrt{1 - \dfrac{9}{25}} = \dfrac{4}{5}$.', 'Ellipse'),
  ('The foci of the ellipse $\dfrac{x^{2}}{25} + \dfrac{y^{2}}{9} = 1$ are:', '["$(0, \\pm 4)$","$(\\pm 4, 0)$","$(\\pm 5, 0)$","$(\\pm 3, 0)$"]'::jsonb, 1, '$c^{2} = a^{2} - b^{2} = 25 - 9 = 16$, so the foci are $(\pm 4, 0)$.', 'Ellipse'),
  ('The length of the major axis of $\dfrac{x^{2}}{25} + \dfrac{y^{2}}{9} = 1$ is:', '["$5$","$6$","$10$","$25$"]'::jsonb, 2, 'The major axis has length $2a = 10$.', 'Ellipse'),
  ('The eccentricity of the ellipse $\dfrac{x^{2}}{169} + \dfrac{y^{2}}{25} = 1$ is:', '["$\\dfrac{5}{13}$","$\\dfrac{13}{5}$","$\\dfrac{144}{169}$","$\\dfrac{12}{13}$"]'::jsonb, 3, '$e = \sqrt{1 - \dfrac{b^{2}}{a^{2}}} = \sqrt{1 - \dfrac{25}{169}} = \dfrac{12}{13}$.', 'Ellipse'),
  ('The foci of the ellipse $\dfrac{x^{2}}{169} + \dfrac{y^{2}}{25} = 1$ are:', '["$(\\pm 12, 0)$","$(0, \\pm 12)$","$(\\pm 13, 0)$","$(\\pm 5, 0)$"]'::jsonb, 0, '$c^{2} = a^{2} - b^{2} = 169 - 25 = 144$, so the foci are $(\pm 12, 0)$.', 'Ellipse'),
  ('The length of the major axis of $\dfrac{x^{2}}{169} + \dfrac{y^{2}}{25} = 1$ is:', '["$13$","$26$","$10$","$169$"]'::jsonb, 1, 'The major axis has length $2a = 26$.', 'Ellipse'),
  ('The eccentricity of the ellipse $\dfrac{x^{2}}{100} + \dfrac{y^{2}}{36} = 1$ is:', '["$\\dfrac{3}{5}$","$\\dfrac{5}{3}$","$\\dfrac{4}{5}$","$\\dfrac{16}{25}$"]'::jsonb, 2, '$e = \sqrt{1 - \dfrac{b^{2}}{a^{2}}} = \sqrt{1 - \dfrac{36}{100}} = \dfrac{4}{5}$.', 'Ellipse'),
  ('The foci of the ellipse $\dfrac{x^{2}}{100} + \dfrac{y^{2}}{36} = 1$ are:', '["$(0, \\pm 8)$","$(\\pm 10, 0)$","$(\\pm 6, 0)$","$(\\pm 8, 0)$"]'::jsonb, 3, '$c^{2} = a^{2} - b^{2} = 100 - 36 = 64$, so the foci are $(\pm 8, 0)$.', 'Ellipse'),
  ('The length of the major axis of $\dfrac{x^{2}}{100} + \dfrac{y^{2}}{36} = 1$ is:', '["$20$","$10$","$12$","$100$"]'::jsonb, 0, 'The major axis has length $2a = 20$.', 'Ellipse'),
  ('The eccentricity of the ellipse $\dfrac{x^{2}}{16} + \dfrac{y^{2}}{9} = 1$ is:', '["$\\dfrac{3}{4}$","$\\dfrac{\\sqrt{7}}{4}$","$\\dfrac{4}{3}$","$\\dfrac{7}{16}$"]'::jsonb, 1, '$e = \sqrt{1 - \dfrac{b^{2}}{a^{2}}} = \sqrt{1 - \dfrac{9}{16}} = \dfrac{\sqrt{7}}{4}$.', 'Ellipse'),
  ('The length of the major axis of $\dfrac{x^{2}}{16} + \dfrac{y^{2}}{9} = 1$ is:', '["$4$","$6$","$8$","$16$"]'::jsonb, 2, 'The major axis has length $2a = 8$.', 'Ellipse'),
  ('The eccentricity of the hyperbola $\dfrac{x^{2}}{16} - \dfrac{y^{2}}{9} = 1$ is:', '["$\\dfrac{3}{4}$","$\\dfrac{4}{3}$","$\\dfrac{7}{16}$","$\\dfrac{5}{4}$"]'::jsonb, 3, '$e = \sqrt{1 + \dfrac{b^{2}}{a^{2}}} = \sqrt{1 + \dfrac{9}{16}} = \dfrac{5}{4}$.', 'Hyperbola'),
  ('The asymptotes of the hyperbola $\dfrac{x^{2}}{16} - \dfrac{y^{2}}{9} = 1$ are:', '["$y = \\pm \\dfrac{3}{4}x$","$y = \\pm \\dfrac{4}{3}x$","$y = \\pm \\dfrac{9}{16}x$","$y = \\pm 3x$"]'::jsonb, 0, 'The asymptotes are $y = \pm\dfrac{b}{a}x = \pm\dfrac{3}{4}x$.', 'Hyperbola'),
  ('The eccentricity of the hyperbola $\dfrac{x^{2}}{9} - \dfrac{y^{2}}{16} = 1$ is:', '["$\\dfrac{4}{3}$","$\\dfrac{5}{3}$","$\\dfrac{3}{4}$","$\\dfrac{7}{9}$"]'::jsonb, 1, '$e = \sqrt{1 + \dfrac{b^{2}}{a^{2}}} = \sqrt{1 + \dfrac{16}{9}} = \dfrac{5}{3}$.', 'Hyperbola'),
  ('The asymptotes of the hyperbola $\dfrac{x^{2}}{9} - \dfrac{y^{2}}{16} = 1$ are:', '["$y = \\pm \\dfrac{3}{4}x$","$y = \\pm \\dfrac{16}{9}x$","$y = \\pm \\dfrac{4}{3}x$","$y = \\pm 4x$"]'::jsonb, 2, 'The asymptotes are $y = \pm\dfrac{b}{a}x = \pm\dfrac{4}{3}x$.', 'Hyperbola'),
  ('The eccentricity of the hyperbola $\dfrac{x^{2}}{25} - \dfrac{y^{2}}{144} = 1$ is:', '["$\\dfrac{12}{5}$","$\\dfrac{5}{12}$","$\\dfrac{119}{25}$","$\\dfrac{13}{5}$"]'::jsonb, 3, '$e = \sqrt{1 + \dfrac{b^{2}}{a^{2}}} = \sqrt{1 + \dfrac{144}{25}} = \dfrac{13}{5}$.', 'Hyperbola'),
  ('The asymptotes of the hyperbola $\dfrac{x^{2}}{25} - \dfrac{y^{2}}{144} = 1$ are:', '["$y = \\pm \\dfrac{12}{5}x$","$y = \\pm \\dfrac{5}{12}x$","$y = \\pm \\dfrac{144}{25}x$","$y = \\pm 12x$"]'::jsonb, 0, 'The asymptotes are $y = \pm\dfrac{b}{a}x = \pm\dfrac{12}{5}x$.', 'Hyperbola'),
  ('The eccentricity of the hyperbola $\dfrac{x^{2}}{64} - \dfrac{y^{2}}{36} = 1$ is:', '["$\\dfrac{3}{4}$","$\\dfrac{5}{4}$","$\\dfrac{4}{3}$","$\\dfrac{7}{16}$"]'::jsonb, 1, '$e = \sqrt{1 + \dfrac{b^{2}}{a^{2}}} = \sqrt{1 + \dfrac{36}{64}} = \dfrac{5}{4}$.', 'Hyperbola'),
  ('The asymptotes of the hyperbola $\dfrac{x^{2}}{64} - \dfrac{y^{2}}{36} = 1$ are:', '["$y = \\pm \\dfrac{4}{3}x$","$y = \\pm \\dfrac{9}{16}x$","$y = \\pm \\dfrac{3}{4}x$","$y = \\pm 6x$"]'::jsonb, 2, 'The asymptotes are $y = \pm\dfrac{b}{a}x = \pm\dfrac{3}{4}x$.', 'Hyperbola'),
  ('The conic $x^{2} + y^{2} - 4 = 0$ represents:', '["a parabola","an ellipse","a hyperbola","a circle"]'::jsonb, 3, 'Using $b^{2} - 4ac$ with $a = 1$, $b = 0$, $c = 1$ gives -4 (negative: an ellipse, or a circle when $a = c$). This is a circle.', 'Classification of Conics'),
  ('The conic $x^{2} - 4y = 0$ represents:', '["a parabola","a circle","an ellipse","a hyperbola"]'::jsonb, 0, 'Using $b^{2} - 4ac$ with $a = 1$, $b = 0$, $c = 0$ gives 0 (zero: a parabola). This is a parabola.', 'Classification of Conics'),
  ('The conic $4x^{2} + 9y^{2} = 36$ represents:', '["a circle","an ellipse","a parabola","a hyperbola"]'::jsonb, 1, 'Using $b^{2} - 4ac$ with $a = 4$, $b = 0$, $c = 9$ gives -144 (negative: an ellipse, or a circle when $a = c$). This is an ellipse.', 'Classification of Conics'),
  ('The conic $x^{2} - y^{2} = 9$ represents:', '["a circle","a parabola","a hyperbola","an ellipse"]'::jsonb, 2, 'Using $b^{2} - 4ac$ with $a = 1$, $b = 0$, $c = -1$ gives 4 (positive: a hyperbola). This is a hyperbola.', 'Classification of Conics'),
  ('The cosine of the angle between $\mathbf{v}_{1} = \mathbf{i}+2\mathbf{j}-\mathbf{k}$ and $\mathbf{v}_{2} = -\mathbf{i}+\mathbf{j}-2\mathbf{k}$ is:', '["$\\dfrac{1}{6}$","$\\dfrac{5}{6}$","$\\dfrac{3}{\\sqrt{6}}$","$\\dfrac{1}{2}$"]'::jsonb, 3, '$\mathbf{v}_{1}\cdot\mathbf{v}_{2} = -1 + 2 + 2 = 3$ and $|\mathbf{v}_{1}||\mathbf{v}_{2}| = \sqrt{6}\cdot\sqrt{6} = 6$, so $\cos\theta = \dfrac{3}{6} = \dfrac{1}{2}$.', 'Dot Product'),
  ('The value of $p$ for which $2\mathbf{i} + p\mathbf{j} + \mathbf{k}$ and $4\mathbf{i} - 2\mathbf{j} - 2\mathbf{k}$ are perpendicular is:', '["$3$","$-3$","$2$","$-2$"]'::jsonb, 0, 'Perpendicular vectors have zero dot product: $8 - 2p - 2 = 0$, so $p = 3$.', 'Dot Product'),
  ('The value of $\lambda$ for which $2\mathbf{i} + 3\mathbf{j} + \mathbf{k}$ and $4\mathbf{i} - 2\mathbf{j} + \lambda\mathbf{k}$ are perpendicular is:', '["$2$","$-2$","$-14$","$14$"]'::jsonb, 1, '$8 - 6 + \lambda = 0$, so $\lambda = -2$.', 'Dot Product'),
  ('The value of $m$ for which $3\mathbf{i} - 2\mathbf{j}$ and $4\mathbf{i} - m\mathbf{j}$ are parallel is:', '["$\\dfrac{3}{8}$","$-\\dfrac{8}{3}$","$\\dfrac{8}{3}$","$6$"]'::jsonb, 2, 'Parallel vectors have proportional components: $\dfrac{3}{4} = \dfrac{-2}{-m}$, so $m = \dfrac{8}{3}$.', 'Parallel Vectors'),
  ('The direction cosines of $-2\mathbf{i} + 4\mathbf{j} - 3\mathbf{k}$ are:', '["$\\left(\\dfrac{-2}{\\sqrt{29}}, \\dfrac{4}{\\sqrt{29}}, \\dfrac{-3}{\\sqrt{29}}\\right)$","$\\left(\\dfrac{2}{\\sqrt{29}}, \\dfrac{4}{\\sqrt{29}}, \\dfrac{3}{\\sqrt{29}}\\right)$","$\\left(\\dfrac{-2}{29}, \\dfrac{4}{29}, \\dfrac{-3}{29}\\right)$","$\\left(\\dfrac{-2}{3}, \\dfrac{4}{3}, -1\\right)$"]'::jsonb, 0, 'The magnitude is $\sqrt{4 + 16 + 9} = \sqrt{29}$. Each component is divided by the magnitude.', 'Direction Cosines'),
  ('The angle between $2\mathbf{i} - 3\mathbf{j} + 5\mathbf{k}$ and $-6\mathbf{i} + 9\mathbf{j} - 15\mathbf{k}$ is:', '["$0^{\\circ}$","$180^{\\circ}$","$90^{\\circ}$","$60^{\\circ}$"]'::jsonb, 1, 'The second vector is $-3$ times the first, so the vectors are parallel but point in opposite directions: the angle is $180^{\circ}$.', 'Dot Product'),
  ('The vector product $3\mathbf{j}\times 2\mathbf{k}$ is:', '["$-6\\mathbf{i}$","$6\\mathbf{j}$","$6\\mathbf{i}$","$5\\mathbf{i}$"]'::jsonb, 2, '$\mathbf{j}\times\mathbf{k} = \mathbf{i}$, so $3\mathbf{j}\times2\mathbf{k} = 6\mathbf{i}$.', 'Vector Product'),
  ('The area of the parallelogram with adjacent sides $3\mathbf{i}+5\mathbf{j}-\mathbf{k}$ and $2\mathbf{i}-4\mathbf{k}$ is:', '["$\\sqrt{610}$","$10\\sqrt{7}$","$\\sqrt{13}$","$10\\sqrt{6}$"]'::jsonb, 3, '$\mathbf{a}\times\mathbf{b} = -20\mathbf{i}+10\mathbf{j}-10\mathbf{k}$, with magnitude $\sqrt{600}$. The area equals this magnitude.', 'Vector Product'),
  ('The vectors $(1, 2, 3)$, $(2, 4, 2)$ and $(1, 2, 5)$ are:', '["linearly dependent","linearly independent","mutually orthogonal","unit vectors"]'::jsonb, 0, 'The scalar triple product is $\begin{vmatrix}1 & 2 & 3\\ 2 & 4 & 2\\ 1 & 2 & 5\end{vmatrix} = 0$. Since it is zero (the second column is twice the first), the vectors are linearly dependent.', 'Linear Independence'),
  ('Are the vectors $(1, 2, 1)$ and $(-2, 1, 0)$ orthogonal?', '["No, because their dot product is 3","Yes, because their dot product is 0","No, because their dot product is -4","Yes, because their cross product is 0"]'::jsonb, 1, '$(1)(-2) + (2)(1) + (1)(0) = 0$, so the vectors are orthogonal.', 'Dot Product'),
  ('Let $\mathbf{v}_{1} = 2\mathbf{i} - \mathbf{j} + \mathbf{k}$, $\mathbf{v}_{2} = \mathbf{i} - 3\mathbf{j} - 2\mathbf{k}$, $\mathbf{v}_{3} = -2\mathbf{i} + \mathbf{j} - 3\mathbf{k}$ and $\mathbf{v}_{4} = 3\mathbf{i} + 2\mathbf{j} + 5\mathbf{k}$. If $\mathbf{v}_{4} = a\mathbf{v}_{1} + b\mathbf{v}_{2} + c\mathbf{v}_{3}$, then $b$ equals:', '["$\\dfrac{7}{5}$","$\\dfrac{-2}{5}$","$\\dfrac{-7}{5}$","$\\dfrac{-14}{5}$"]'::jsonb, 2, 'Comparing components: $2a + b - 2c = 3$, $-a - 3b + c = 2$, $a - 2b - 3c = 5$. Solving gives $a = 2.2$, $b = -1.4$, $c = 0$ (check: all three components match).', 'Linear Independence'),
  ('Find $\mathbf{u}\cdot\mathbf{v}$ for $\mathbf{u} = \mathbf{i}+2\mathbf{j}+3\mathbf{k}$ and $\mathbf{v} = 2\mathbf{i}-\mathbf{j}+4\mathbf{k}$.', '["$13$","$11$","$24$","$12$"]'::jsonb, 3, '$\mathbf{u}\cdot\mathbf{v} = (1)(2) + (2)(-1) + (3)(4) = 12$.', 'Dot Product'),
  ('Find $\mathbf{u}\cdot\mathbf{v}$ for $\mathbf{u} = 3\mathbf{i}-\mathbf{k}$ and $\mathbf{v} = 2\mathbf{i}+5\mathbf{j}+\mathbf{k}$.', '["$5$","$6$","$4$","$10$"]'::jsonb, 0, '$\mathbf{u}\cdot\mathbf{v} = (3)(2) + (0)(5) + (-1)(1) = 5$.', 'Dot Product'),
  ('Find $\mathbf{u}\cdot\mathbf{v}$ for $\mathbf{u} = 2\mathbf{i}+2\mathbf{j}+\mathbf{k}$ and $\mathbf{v} = \mathbf{i}-2\mathbf{j}+2\mathbf{k}$.', '["$1$","$0$","$-1$","$2$"]'::jsonb, 1, '$\mathbf{u}\cdot\mathbf{v} = (2)(1) + (2)(-2) + (1)(2) = 0$.', 'Dot Product'),
  ('The magnitude of the vector $2\mathbf{i}+3\mathbf{j}+6\mathbf{k}$ is:', '["$3\\sqrt{6}$","$11$","$7$","$3\\sqrt{5}$"]'::jsonb, 2, '$|\mathbf{v}| = \sqrt{4 + 9 + 36} = \sqrt{49} = 7$.', 'Vectors in Three Dimensions'),
  ('The magnitude of the vector $\mathbf{i}+2\mathbf{j}+2\mathbf{k}$ is:', '["$\\sqrt{14}$","$5$","$\\sqrt{5}$","$3$"]'::jsonb, 3, '$|\mathbf{v}| = \sqrt{1 + 4 + 4} = \sqrt{9} = 3$.', 'Vectors in Three Dimensions'),
  ('The magnitude of the vector $3\mathbf{i}+4\mathbf{j}+12\mathbf{k}$ is:', '["$13$","$\\sqrt{174}$","$19$","$\\sqrt{165}$"]'::jsonb, 0, '$|\mathbf{v}| = \sqrt{9 + 16 + 144} = \sqrt{169} = 13$.', 'Vectors in Three Dimensions'),
  ('The magnitude of the vector $2\mathbf{i}-3\mathbf{j}+6\mathbf{k}$ is:', '["$3\\sqrt{6}$","$7$","$11$","$3\\sqrt{5}$"]'::jsonb, 1, '$|\mathbf{v}| = \sqrt{4 + 9 + 36} = \sqrt{49} = 7$.', 'Vectors in Three Dimensions'),
  ('Find the volume of the parallelepiped with edges $\mathbf{i}+2\mathbf{j}+3\mathbf{k}$, $2\mathbf{i}+\mathbf{k}$ and $\mathbf{i}+\mathbf{j}+4\mathbf{k}$.', '["$10$","$8$","$9$","$18$"]'::jsonb, 2, 'Volume $= |\mathbf{a}\cdot(\mathbf{b}\times\mathbf{c})|$. $\mathbf{b}\times\mathbf{c} = -\mathbf{i}-7\mathbf{j}+2\mathbf{k}$ and its dot product with $\mathbf{a}$ is -9$, so the volume is 9.', 'Scalar Triple Product'),
  ('The component (scalar projection) of $3\mathbf{i} + 4\mathbf{j}$ in the direction of $\mathbf{i}$ is:', '["$4$","$5$","$7$","$3$"]'::jsonb, 3, '$\dfrac{\mathbf{u}\cdot\mathbf{v}}{|\mathbf{v}|} = \dfrac{3}{1} = 3$.', 'Dot Product'),
  ('A unit vector in the direction of $3\mathbf{i} - 4\mathbf{j}$ is:', '["$\\dfrac{3}{5}\\mathbf{i} - \\dfrac{4}{5}\\mathbf{j}$","$3\\mathbf{i} - 4\\mathbf{j}$","$\\dfrac{1}{5}\\mathbf{i} - \\dfrac{1}{5}\\mathbf{j}$","$\\dfrac{4}{5}\\mathbf{i} - \\dfrac{3}{5}\\mathbf{j}$"]'::jsonb, 0, 'Divide by the magnitude $\sqrt{9 + 16} = 5$.', 'Vectors in Three Dimensions')
),
tgt as (
  select subject_id, subject_name, faculty, department, level, semester, units
    from public.cbt_questions
   where subject_name ilike 'MTH 102%' and subject_id not like '%coming-soon'
   limit 1
)
insert into public.cbt_questions
  (subject_id, subject_name, institution, faculty, department, level,
   question, options, correct_index, explanation, topic, is_general, semester, units)
select coalesce(t.subject_id, 'mth-102-vectors-geometry-dynamics'),
       coalesce(t.subject_name, 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics'),
       'University of Nigeria, Nsukka',
       coalesce(t.faculty, 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences, Faculty of Education'),
       coalesce(t.department, 'Mathematics'),
       coalesce(t.level, '100 Level'),
       s.question, s.options, s.correct_index, s.explanation, s.topic, false,
       coalesce(t.semester, 'second'),
       coalesce(t.units, 3)
  from src s
  left join tgt t on true
 where not exists (
   select 1 from public.cbt_questions c
    where c.subject_id = coalesce(t.subject_id, 'mth-102-vectors-geometry-dynamics') and c.question = s.question);

select subject_id, subject_name, count(*) as questions
  from public.cbt_questions
 where subject_name ilike 'MTH 102%' and subject_id not like '%coming-soon'
 group by 1, 2;


-- ============ PART 4: unn_mth102_ca_workbook_cbt_questions.sql ============
-- MTH 102 (old MTH 122): questions from the MTH 122 CA workbook (Practice Sets 1 to 3 and Chapter 3)
-- =============================================================================
-- 92 questions. Every answer was re-solved; the circled answers and handwritten
-- solutions in the scan were NOT trusted. Corrections to the scan: the angle between
-- 3x + 3y - 1 = 0 and 4x - 3y + 8 = 0 is tan^-1(7); parallel-line distance 12/13;
-- the line through (1,2) and (-1,0) is y = x + 1; the tangents from (-1,-1) to
-- x^2 = 8y have gradients 1/2 and -1; the tangents from the origin to
-- x^2 + y^2 + 8x + 6y + 21 = 0 meet at about 47.2 degrees (not 25.1); the plane
-- through P, Q, R is 11x + 5y + 13z = 30. About a dozen scan items had no correct
-- option or inconsistent data (for example a point not lying on its own circle) and
-- were dropped.
-- ADDS ONLY to the existing MTH 102 paper; repeats are skipped.
-- =============================================================================
with src (question, options, correct_index, explanation, topic) as (
values
  ('The point of intersection of the lines $3x + 5y = 5$ and $y = 2x + 14$ is:', '["$(-5, 4)$","$(5, -4)$","$(-4, 5)$","$(4, 5)$"]'::jsonb, 0, 'Substitute $y = 2x + 14$: $3x + 10x + 70 = 5$, so $13x = -65$, $x = -5$ and $y = 4$.', 'Intersection of Lines'),
  ('The equation of the line through $(1, -2)$ parallel to $x + 2y = 4$ is:', '["$x + 2y - 3 = 0$","$x + 2y + 3 = 0$","$2x - y - 4 = 0$","$x - 2y - 5 = 0$"]'::jsonb, 1, 'A parallel line has the same gradient: $x + 2y + c = 0$. At $(1, -2)$: $1 - 4 + c = 0$, so $c = 3$.', 'Parallel and Perpendicular Lines'),
  ('The distance from the point $(1, 2)$ to the line $3x - 4y = 5$ is:', '["1","3","2","5"]'::jsonb, 2, '$d = \dfrac{|3(1) - 4(2) - 5|}{\sqrt{9 + 16}} = \dfrac{10}{5} = 2$.', 'Distance of a Point from a Line'),
  ('The mid-point of the line joining $\left(3, \tfrac{1}{3}\right)$ and $\left(2, \tfrac{1}{2}\right)$ is:', '["$\\left(\\dfrac{5}{2}, \\dfrac{5}{6}\\right)$","$\\left(5, \\dfrac{5}{6}\\right)$","$\\left(\\dfrac{5}{2}, \\dfrac{1}{12}\\right)$","$\\left(\\dfrac{5}{2}, \\dfrac{5}{12}\\right)$"]'::jsonb, 3, 'Mid-point $= \left(\dfrac{3 + 2}{2}, \dfrac{1/3 + 1/2}{2}\right) = \left(\dfrac{5}{2}, \dfrac{5}{12}\right)$.', 'Straight Line'),
  ('The slope and $y$-intercept of the line $5x - 7y + 13 = 0$ are respectively:', '["$\\dfrac{5}{7}$ and $\\dfrac{13}{7}$","$-\\dfrac{5}{7}$ and $-\\dfrac{13}{7}$","$\\dfrac{7}{5}$ and $\\dfrac{13}{5}$","$-\\dfrac{7}{5}$ and $\\dfrac{13}{7}$"]'::jsonb, 0, 'Writing $y = \dfrac{5}{7}x + \dfrac{13}{7}$ gives slope $\tfrac{5}{7}$ and intercept $\tfrac{13}{7}$.', 'Equation of a Straight Line'),
  ('The equation of the line through $(1, 2)$ perpendicular to $4x + 3y + 12 = 0$ is:', '["$4x - 3y + 5 = 0$","$3x - 4y + 5 = 0$","$3x + 4y - 5 = 0$","$3x - 4y - 3 = 0$"]'::jsonb, 1, 'The given line has gradient $-\tfrac{4}{3}$, so the perpendicular has gradient $\tfrac{3}{4}$: $y - 2 = \tfrac{3}{4}(x - 1)$, i.e. $3x - 4y + 5 = 0$.', 'Parallel and Perpendicular Lines'),
  ('The equation of the line through $(1, 2)$ parallel to $2x + 5y + 9 = 0$ is:', '["$5x - 2y - 12 = 0$","$2x - 5y + 12 = 0$","$2x + 5y - 12 = 0$","$5x - 2y + 12 = 0$"]'::jsonb, 2, '$2x + 5y + c = 0$ with $2 + 10 + c = 0$ gives $c = -12$.', 'Parallel and Perpendicular Lines'),
  ('The perpendicular distance of $(-2, 3)$ from the line $4x - 3y = 8$ is:', '["3/5","-5","5/3","5"]'::jsonb, 3, '$d = \dfrac{|4(-2) - 3(3) - 8|}{5} = \dfrac{25}{5} = 5$.', 'Distance of a Point from a Line'),
  ('The acute angle between the lines $3x + 3y - 1 = 0$ and $4x - 3y + 8 = 0$ is:', '["$\\tan^{-1}(7)$","$\\tan^{-1}\\left(\\dfrac{7}{3}\\right)$","$\\tan^{-1}(-7)$","$\\tan^{-1}(1)$"]'::jsonb, 0, 'The gradients are $m_{1} = -1$ and $m_{2} = \tfrac{4}{3}$. $\tan\theta = \left|\dfrac{m_{1} - m_{2}}{1 + m_{1}m_{2}}\right| = \left|\dfrac{-7/3}{-1/3}\right| = 7$.', 'Angle Between Two Lines'),
  ('The area of the triangle with vertices $(1, 4)$, $(-2, 8)$ and $(-7, -7)$ is:', '["$23\\tfrac{1}{2}$","$32\\tfrac{1}{2}$","$32\\tfrac{1}{5}$","$27$"]'::jsonb, 1, 'Area $= \tfrac{1}{2}|1(8 + 7) + (-2)(-7 - 4) + (-7)(4 - 8)| = \tfrac{1}{2}(15 + 22 + 28) = 32.5$.', 'Area of a Triangle'),
  ('The line through the mid-point of $(-2, 3)$ and $(4, 5)$ parallel to $2y - x = 6$ is:', '["$y - x - 7 = 0$","$2y + x - 7 = 0$","$2y - x - 7 = 0$","$x + y - 7 = 0$"]'::jsonb, 2, 'Mid-point $= (1, 4)$. The gradient of $2y - x = 6$ is $\tfrac{1}{2}$, so $y - 4 = \tfrac{1}{2}(x - 1)$, i.e. $2y - x - 7 = 0$.', 'Straight Line'),
  ('The point dividing the line joining $(a, 0)$ and $(0, a)$ internally in the ratio $a : 2a$ is:', '["$\\left(\\dfrac{a}{3}, \\dfrac{2a}{3}\\right)$","$\\left(-\\dfrac{a}{3}, \\dfrac{3a}{3}\\right)$","$\\left(\\dfrac{2a}{3}, -\\dfrac{a}{3}\\right)$","$\\left(\\dfrac{2a}{3}, \\dfrac{a}{3}\\right)$"]'::jsonb, 3, 'The ratio is $1 : 2$. $x = \dfrac{1(0) + 2(a)}{3} = \dfrac{2a}{3}$ and $y = \dfrac{1(a) + 2(0)}{3} = \dfrac{a}{3}$.', 'Division of a Line Segment'),
  ('The equation of the line through $(a, 0)$ and $(0, b)$ is:', '["$bx + ay = ab$","$ay - bx = ab$","$x + y = a$","$x + y = b$"]'::jsonb, 0, 'Intercept form: $\dfrac{x}{a} + \dfrac{y}{b} = 1$, i.e. $bx + ay = ab$.', 'Equation of a Straight Line'),
  ('The line through $A(1, 2)$ and $B(-1, 0)$ has the equation:', '["$x + 2y = 1$","$y = x + 1$","$y + x = 1$","$y = 2x$"]'::jsonb, 1, 'Gradient $= \dfrac{2 - 0}{1 - (-1)} = 1$, so $y - 0 = 1(x + 1)$, i.e. $y = x + 1$.', 'Equation of a Straight Line'),
  ('The distance between the parallel lines $12x + 5y - 7 = 0$ and $12x + 5y + 5 = 0$ is:', '["$\\dfrac{5}{2}$","$\\dfrac{13}{5}$","$\\dfrac{12}{13}$","$\\dfrac{2}{5}$"]'::jsonb, 2, '$d = \dfrac{|c_{1} - c_{2}|}{\sqrt{a^{2} + b^{2}}} = \dfrac{|-7 - 5|}{13} = \dfrac{12}{13}$.', 'Distance of a Point from a Line'),
  ('A line makes an intercept $-\dfrac{5}{3}$ on the $x$-axis and $4$ on the $y$-axis. Its equation is:', '["$12x + 5y + 20 = 0$","$12x - 5y - 20 = 0$","$5x - 12y + 20 = 0$","$12x - 5y + 20 = 0$"]'::jsonb, 3, '$\dfrac{x}{-5/3} + \dfrac{y}{4} = 1$ gives $-\dfrac{3x}{5} + \dfrac{y}{4} = 1$; multiplying by 20: $-12x + 5y = 20$, i.e. $12x - 5y + 20 = 0$.', 'Equation of a Straight Line'),
  ('The point dividing the line joining $A\left(-\dfrac{3}{2}, 2\right)$ and $B\left(\dfrac{5}{2}, 3\right)$ externally in the ratio $3 : 2$ is:', '["$\\left(\\dfrac{21}{2}, 5\\right)$","$\\left(5, \\dfrac{21}{2}\\right)$","$\\left(\\dfrac{9}{10}, \\dfrac{13}{5}\\right)$","$\\left(\\dfrac{13}{5}, \\dfrac{9}{10}\\right)$"]'::jsonb, 0, 'External division: $x = \dfrac{3(5/2) - 2(-3/2)}{3 - 2} = \dfrac{15/2 + 3}{1} = \dfrac{21}{2}$; $y = \dfrac{3(3) - 2(2)}{1} = 5$.', 'Division of a Line Segment'),
  ('The intercepts of the line $2x + 3y = 13$ on the coordinate axes are:', '["$\\left(0, \\dfrac{13}{3}\\right)$ and $\\left(\\dfrac{13}{2}, 0\\right)$ swapped, $(13, 0)$ and $(0, 13)$","$\\left(\\dfrac{13}{2}, 0\\right)$ and $\\left(0, \\dfrac{13}{3}\\right)$","$\\left(\\dfrac{13}{3}, 0\\right)$ and $\\left(0, \\dfrac{13}{2}\\right)$","$(2, 0)$ and $(0, 3)$"]'::jsonb, 1, 'Setting $y = 0$ gives $x = \tfrac{13}{2}$; setting $x = 0$ gives $y = \tfrac{13}{3}$.', 'Equation of a Straight Line'),
  ('Find $p$ if the area of the triangle with vertices $A(p, 0)$, $B(2, 0)$ and $C(-1, -2)$ is 7 square units and $p < 0$.', '["$2$","$7$","$-5$","$3$"]'::jsonb, 2, 'Taking $AB$ as base, the base is $|p - 2|$ and the height is $2$, so the area is $|p - 2| = 7$. Hence $p = 9$ or $p = -5$; with $p < 0$, $p = -5$.', 'Area of a Triangle'),
  ('The distance between $A(c, d)$ and $B(d, c)$ is:', '["$\\sqrt{d - c}$","$d - c$","$\\sqrt{2}\\,(d + c)$","$\\sqrt{2}\\,|d - c|$"]'::jsonb, 3, '$|AB| = \sqrt{(d - c)^{2} + (c - d)^{2}} = \sqrt{2(d - c)^{2}} = \sqrt{2}\,|d - c|$.', 'Straight Line'),
  ('If $A(-1, 1)$, $B(3, 3)$ and $C(1, -1)$ are the vertices of a triangle, then triangle $ABC$ is:', '["isosceles","scalene","obtuse","right-angled"]'::jsonb, 0, '$AB^{2} = 16 + 4 = 20$, $BC^{2} = 4 + 16 = 20$ and $AC^{2} = 4 + 4 = 8$. Two sides are equal, so the triangle is isosceles.', 'Straight Line'),
  ('Find the equation of the line passing through the point of intersection of $3x + y + 1 = 0$ and $y = 3x + 1$ and parallel to $4x - y = 7$.', '["$12x + 3y + 4 = 0$","$12x - 3y + 4 = 0$","$4x - y + 4 = 0$","$3x - 12y + 1 = 0$"]'::jsonb, 1, 'Intersection: $3x + 3x + 1 + 1 = 0$ gives $x = -\tfrac{1}{3}$, $y = 0$. Gradient $4$: $y = 4\left(x + \tfrac{1}{3}\right)$, i.e. $12x - 3y + 4 = 0$.', 'Pencil of Lines'),
  ('Two vertices of an equilateral triangle are $(0, 2)$ and $(0, 6)$. A possible third vertex is:', '["$(2, 4)$","$(4, 4)$","$(2\\sqrt{3}, 4)$","$(\\sqrt{3}, 4)$"]'::jsonb, 2, 'The side is 4, so the height is $\tfrac{\sqrt{3}}{2}\times4 = 2\sqrt{3}$, measured horizontally from the mid-point $(0, 4)$. The third vertex is $(\pm2\sqrt{3}, 4)$.', 'Straight Line'),
  ('A pentagon has vertices $P(4, 2)$, $Q(-2, 8)$, $R(-6, -11)$, $S(1, -11)$ and $T(8, -1)$. Its area is:', '["290 square units","170 square units","125 square units","145 square units"]'::jsonb, 3, 'Using the shoelace formula, the sum of $x_{i}y_{i+1} - x_{i+1}y_{i}$ is 290$, so the area is $\tfrac{1}{2}(290) = 145$.', 'Area of a Polygon'),
  ('The centre and radius of the circle $4x^{2} + 4y^{2} - 3x - 8y - 1 = 0$ are:', '["$\\left(\\dfrac{3}{8}, 1\\right)$ and $\\dfrac{\\sqrt{89}}{8}$","$\\left(-\\dfrac{3}{8}, -1\\right)$ and $\\dfrac{\\sqrt{89}}{8}$","$(-3, -8)$ and $\\dfrac{89}{8}$","$(3, 8)$ and $\\dfrac{9}{8}$"]'::jsonb, 0, 'Divide by 4: $x^{2} + y^{2} - \tfrac{3}{4}x - 2y - \tfrac{1}{4} = 0$. Centre $\left(\tfrac{3}{8}, 1\right)$ and $r^{2} = \tfrac{9}{64} + 1 + \tfrac{1}{4} = \tfrac{89}{64}$.', 'Equation of a Circle'),
  ('The equation of the circle through the origin that cuts off intercepts 3 and 2 on the $x$- and $y$-axes is:', '["$x^{2} + y^{2} + 3x - 3y = 0$","$x^{2} + y^{2} - 3x - 2y = 0$","$x^{2} + y^{2} - 4x - 3y = 0$","$2x^{2} + y^{2} + 3x + 2y = 0$"]'::jsonb, 1, 'The circle passes through $(0, 0)$, $(3, 0)$ and $(0, 2)$. With $x^{2} + y^{2} + Dx + Ey = 0$: $9 + 3D = 0$ and $4 + 2E = 0$, so $D = -3$, $E = -2$.', 'Equation of a Circle'),
  ('One of the points of intersection of the line $3x - y + 5 = 0$ and the circle $x^{2} + y^{2} = 25$ is:', '["$(5, 9)$","$(-3, 2)$","$(0, 5)$","$(2, 5 - 4)$"]'::jsonb, 2, 'Substituting $y = 3x + 5$: $10x^{2} + 30x = 0$, so $x = 0$ or $x = -3$, giving $(0, 5)$ and $(-3, -4)$.', 'Intersection of a Line and a Circle'),
  ('The point $(3, 1)$ lies ______ the circle $4x^{2} + 4y^{2} - 3x - 8y - 1 = 0$.', '["inside","on","at the centre of","outside"]'::jsonb, 3, 'Substituting: $36 + 4 - 9 - 8 - 1 = 22 > 0$, so the point lies outside the circle.', 'Equation of a Circle'),
  ('The equation of the tangent to the circle $x^{2} + y^{2} - 4x - 6y + 3 = 0$ at the point $(1, 6)$ is:', '["$x - 3y + 17 = 0$","$3y - x + 17 = 0$","$3y + x + 17 = 0$","$17 - 3y - x = 0$"]'::jsonb, 0, 'The point lies on the circle ($1 + 36 - 4 - 36 + 3 = 0$). The tangent at $(x_{1}, y_{1})$ is $xx_{1} + yy_{1} - 2(x + x_{1}) - 3(y + y_{1}) + 3 = 0$, which gives $-x + 3y - 17 = 0$, i.e. $x - 3y + 17 = 0$.', 'Tangents to a Circle'),
  ('If $x + y = c$ is tangent to the circle $x^{2} + y^{2} - 4x + 2 = 0$, the values of $c$ are:', '["$4$ and $-1$","$0$ and $4$","$1$ and $4$","$0$ and $-4$"]'::jsonb, 1, 'The centre is $(2, 0)$ and $r = \sqrt{2}$. The distance from the centre to $x + y - c = 0$ is $\dfrac{|2 - c|}{\sqrt{2}} = \sqrt{2}$, so $|2 - c| = 2$ and $c = 0$ or $4$.', 'Tangents to a Circle'),
  ('If $C(-5, 3)$ is a given point and $P(x, y)$ moves so that $PC = 2$, the equation of the locus of $P$ is:', '["$x^{2} + y^{2} + 10x - 6y - 30 = 0$","$x^{2} + y^{2} + 6x - 10y + 10 = 0$","$x^{2} + y^{2} + 10x - 6y + 30 = 0$","$x^{2} + y^{2} - 10x + 6y + 30 = 0$"]'::jsonb, 2, '$(x + 5)^{2} + (y - 3)^{2} = 4$ expands to $x^{2} + y^{2} + 10x - 6y + 30 = 0$.', 'Locus'),
  ('The circle with $(0, 0)$ and $(2, 2)$ as the ends of a diameter has the equation:', '["$x^{2} + y^{2} + 2x + 2y = 0$","$x^{2} + y^{2} - 2x + 2y = 0$","$x^{2} + y^{2} - 4x + 4y = 0$","$x^{2} + y^{2} - 2x - 2y = 0$"]'::jsonb, 3, '$(x - 0)(x - 2) + (y - 0)(y - 2) = 0$ gives $x^{2} + y^{2} - 2x - 2y = 0$.', 'Equation of a Circle'),
  ('The centre and radius of the circle $x^{2} + y^{2} + 4x - 4y = 1$ are:', '["$(-2, 2)$ and $3$","$(2, -2)$ and $3$","$(-2, 2)$ and $9$","$(2, 3)$ and $3$"]'::jsonb, 0, '$(x + 2)^{2} + (y - 2)^{2} = 1 + 4 + 4 = 9$, so the centre is $(-2, 2)$ and $r = 3$.', 'Equation of a Circle'),
  ('The diameter of the circle $x^{2} + y^{2} + 4x - 4y = 1$ is:', '["3","6","9","27"]'::jsonb, 1, 'The radius is 3, so the diameter is 6.', 'Equation of a Circle'),
  ('The length of the tangent from the point $(2, 3)$ to the circle $x^{2} - 2x + y^{2} + 4y + 4 = 0$ is:', '["2","4","5","$\\sqrt{2}$"]'::jsonb, 2, 'Length $= \sqrt{x_{1}^{2} + y_{1}^{2} - 2x_{1} + 4y_{1} + 4} = \sqrt{4 + 9 - 4 + 12 + 4} = \sqrt{25} = 5$.', 'Tangents to a Circle'),
  ('The normal to the circle $x^{2} + y^{2} - 5x - 4y = 0$ at the point $(5, 2)$ is:', '["$y = 4$","$x + y = 2$","$x + y = 4$","$y = 2$"]'::jsonb, 3, 'The centre is $\left(\tfrac{5}{2}, 2\right)$. The normal passes through the centre and $(5, 2)$, so it is the horizontal line $y = 2$.', 'Tangents to a Circle'),
  ('The chord of contact of the circle $x^{2} + y^{2} = 5$ from the point $(-5, -5)$ is:', '["$x + y + 1 = 0$","$x - y - 1 = 0$","$x + y - 1 = 0$","$y - x + 1 = 0$"]'::jsonb, 0, 'The chord of contact from $(x_{1}, y_{1})$ is $xx_{1} + yy_{1} = r^{2}$: $-5x - 5y = 5$, i.e. $x + y + 1 = 0$.', 'Tangents to a Circle'),
  ('The normal to the circle $x^{2} + y^{2} = 16$ at the point $(-4, 0)$ is:', '["$x = 1$","$y = 0$","$y = x$","$2y = 1$"]'::jsonb, 1, 'The normal passes through the centre $(0, 0)$ and $(-4, 0)$, so it is the $x$-axis, $y = 0$.', 'Tangents to a Circle'),
  ('The length of the tangent from $(5, 12)$ to the circle $2x^{2} + 2y^{2} = 69$ is:', '["$\\dfrac{269}{2}$","$\\dfrac{407}{2}$","$\\sqrt{\\dfrac{269}{2}}$","$\\dfrac{133}{2}$"]'::jsonb, 2, 'The circle is $x^{2} + y^{2} = \tfrac{69}{2}$. Length $= \sqrt{25 + 144 - \tfrac{69}{2}} = \sqrt{\tfrac{269}{2}} \approx 11.6$.', 'Tangents to a Circle'),
  ('The centre and radius of the circle $x^{2} + y^{2} - 2ax + 2ay + a^{2} = 0$ are:', '["$(2a, 2a)$ and $a$","$(-a, a)$ and $0$","$(-a, a)$ and $a$","$(a, -a)$ and $|a|$"]'::jsonb, 3, '$(x - a)^{2} + (y + a)^{2} = a^{2} + a^{2} - a^{2} = a^{2}$.', 'Equation of a Circle'),
  ('The circle through the points $(h, k)$, $(h, 0)$ and $(0, k)$ has the equation:', '["$x^{2} + y^{2} - hx - ky = 0$","$x^{2} + y^{2} + hx + ky = 0$","$x^{2} + y^{2} - hx + ky = 0$","$x^{2} + y^{2} + hx - ky = 0$"]'::jsonb, 0, 'Substituting each of the three points into $x^{2} + y^{2} - hx - ky = 0$ gives $0$, so the circle passes through all of them.', 'Equation of a Circle'),
  ('The circle through the points $(0, 2)$, $(0, 9)$ and $(3, 0)$ has the equation:', '["$x^{2} + y^{2} + 9x + 11y + 18 = 0$","$x^{2} + y^{2} - 9x - 11y + 18 = 0$","$x^{2} + y^{2} - 9x - 11y - 18 = 0$","$x^{2} + y^{2} - 11x - 9y + 18 = 0$"]'::jsonb, 1, 'Let $x^{2} + y^{2} + Dx + Ey + F = 0$. From $(0, 2)$ and $(0, 9)$: $4 + 2E + F = 0$ and $81 + 9E + F = 0$, so $E = -11$, $F = 18$. From $(3, 0)$: $9 + 3D + 18 = 0$, so $D = -9$.', 'Equation of a Circle'),
  ('The radius of the circle $x^{2} + y^{2} - 9x - 11y + 18 = 0$ is:', '["$\\sqrt{130}$","$\\dfrac{\\sqrt{202}}{2}$","$\\dfrac{\\sqrt{130}}{2}$","$\\dfrac{65}{2}$"]'::jsonb, 2, '$r^{2} = \dfrac{81}{4} + \dfrac{121}{4} - 18 = \dfrac{202 - 72}{4} = \dfrac{130}{4}$, so $r = \dfrac{\sqrt{130}}{2}$.', 'Equation of a Circle'),
  ('The equations of the tangents from the origin to the circle $x^{2} + y^{2} - 10x - 6y + 25 = 0$ are:', '["$x = 0$ and $8x - 15y = 0$","$y = 0$ and $8x - 15y = 0$","$y = 5x$ and $y = 3x$","$y = 0$ and $15x - 8y = 0$"]'::jsonb, 3, 'Centre $(5, 3)$, $r = 3$. For $y = mx$: $\dfrac{|5m - 3|}{\sqrt{m^{2} + 1}} = 3$ gives $16m^{2} - 30m = 0$, so $m = 0$ or $m = \tfrac{15}{8}$.', 'Tangents to a Circle'),
  ('The two tangents from the origin to the circle $x^{2} + y^{2} + 8x + 6y + 21 = 0$ make an angle of approximately:', '["47.2°","25.1°","90.0°","36.9°"]'::jsonb, 0, 'The centre is $(-4, -3)$ and $r = 2$, so the distance from the origin to the centre is $d = 5$. The half-angle satisfies $\sin\dfrac{\theta}{2} = \dfrac{r}{d} = \dfrac{2}{5}$, so $\theta = 2\sin^{-1}(0.4) \approx 47.2^{\circ}$.', 'Tangents to a Circle'),
  ('If $y = mx + 5$ is a tangent to the circle $x^{2} + y^{2} = 5$, then $m$ equals:', '["$\\pm 1$","$\\pm 2$","$\\pm 4$","$\\pm 5$"]'::jsonb, 1, 'The distance from the origin to $mx - y + 5 = 0$ equals $\sqrt{5}$: $\dfrac{5}{\sqrt{m^{2} + 1}} = \sqrt{5}$, so $m^{2} + 1 = 5$ and $m = \pm 2$.', 'Tangents to a Circle'),
  ('The circle that cuts $S: x^{2} + y^{2} + 6y - 16 = 0$ orthogonally at the points where $S$ meets the line $x + 2y - 4 = 0$ is:', '["$x^{2} + y^{2} + 5x - 4y + 4 = 0$","$x^{2} + y^{2} - 5x + 4y - 4 = 0$","$x^{2} + y^{2} - 5x - 4y + 4 = 0$","$x^{2} + y^{2} - 4x - 5y + 4 = 0$"]'::jsonb, 2, 'Use $S + \lambda L = 0$: $g_{2} = \tfrac{\lambda}{2}$, $f_{2} = 3 + \lambda$, $c_{2} = -16 - 4\lambda$. Orthogonality: $2(g_{1}g_{2} + f_{1}f_{2}) = c_{1} + c_{2}$ gives $6(3 + \lambda) = -32 - 4\lambda$, so $\lambda = -5$.', 'Systems of Circles'),
  ('The conic $12y^{2} - 4x^{2} + 28x - 16 = 0$ is a hyperbola. Its latus rectum has length:', '["$\\sqrt{195}$","$\\dfrac{11}{2}$","$\\dfrac{\\sqrt{33}}{2}$","$\\dfrac{\\sqrt{33}}{3}$"]'::jsonb, 3, 'Completing the square: $4\left(x - \tfrac{7}{2}\right)^{2} - 12y^{2} = 33$, i.e. $\dfrac{(x - 7/2)^{2}}{33/4} - \dfrac{y^{2}}{11/4} = 1$. Latus rectum $= \dfrac{2b^{2}}{a} = \dfrac{11/2}{\sqrt{33}/2} = \dfrac{11}{\sqrt{33}} = \dfrac{\sqrt{33}}{3} \approx 1.915$.', 'Hyperbola'),
  ('The conic $3x^{2} + y^{2} + 2x + 5y = 0$ is:', '["an ellipse","a parabola","a hyperbola","a circle"]'::jsonb, 0, 'The coefficients of $x^{2}$ and $y^{2}$ are both positive and unequal, so it is an ellipse.', 'Classification of Conics'),
  ('The centre of the ellipse $3x^{2} + y^{2} + 2x + 5y = 0$ is:', '["$\\left(\\dfrac{1}{3}, \\dfrac{5}{2}\\right)$","$\\left(-\\dfrac{1}{3}, -\\dfrac{5}{2}\\right)$","$\\left(-\\dfrac{1}{3}, \\dfrac{5}{2}\\right)$","$(-1, -5)$"]'::jsonb, 1, '$3\left(x + \tfrac{1}{3}\right)^{2} + \left(y + \tfrac{5}{2}\right)^{2} = \text{constant}$, so the centre is $\left(-\tfrac{1}{3}, -\tfrac{5}{2}\right)$.', 'Ellipse'),
  ('The asymptotes of the hyperbola $4x^{2} - y^{2} - 1 = 0$ are:', '["$y = x$ and $y = -x$","$y = 4x$ and $y = -4x$","$y = 2x$ and $y = -2x$","$y = \\tfrac{1}{2}x$ and $y = -\\tfrac{1}{2}x$"]'::jsonb, 2, 'The hyperbola is $\dfrac{x^{2}}{1/4} - \dfrac{y^{2}}{1} = 1$, so $y = \pm\dfrac{b}{a}x = \pm2x$.', 'Hyperbola'),
  ('The eccentricity of the conic $4x^{2} + 3y^{2} = 12$ is:', '["$\\dfrac{\\sqrt{3}}{2}$","$\\dfrac{1}{4}$","$2$","$\\dfrac{1}{2}$"]'::jsonb, 3, '$\dfrac{x^{2}}{3} + \dfrac{y^{2}}{4} = 1$ has $a^{2} = 4$, $b^{2} = 3$, so $e = \sqrt{1 - \tfrac{3}{4}} = \tfrac{1}{2}$.', 'Ellipse'),
  ('The equation of the parabola whose directrix is $y = 1$ and focus is $(2, 0)$ is:', '["$x^{2} - 4x + 2y + 3 = 0$","$x^{2} + 4y - 2 = 0$","$x^{2} - 4x - 2y + 3 = 0$","$y^{2} - 4x + 2y + 3 = 0$"]'::jsonb, 0, '$(x - 2)^{2} + y^{2} = (y - 1)^{2}$ gives $x^{2} - 4x + 4 = -2y + 1$, i.e. $x^{2} - 4x + 2y + 3 = 0$.', 'Parabola'),
  ('The centre of the ellipse $\dfrac{(x - 2)^{2}}{9} + \dfrac{(y + 2)^{2}}{5} = 1$ is:', '["$(-2, 2)$","$(2, -2)$","$(4, -2)$","$(2, 2)$"]'::jsonb, 1, 'In the form $\dfrac{(x - h)^{2}}{a^{2}} + \dfrac{(y - k)^{2}}{b^{2}} = 1$ the centre is $(h, k) = (2, -2)$.', 'Ellipse'),
  ('The lengths of the major and minor axes of the ellipse $4(x - 1)^{2} + 9(y - 3)^{2} = 36$ are:', '["2 and 3","36 and 9","6 and 4","3 and 2"]'::jsonb, 2, 'Dividing by 36: $\dfrac{(x - 1)^{2}}{9} + \dfrac{(y - 3)^{2}}{4} = 1$, so $2a = 6$ and $2b = 4$.', 'Ellipse'),
  ('The eccentricity of the ellipse $\dfrac{x^{2}}{9} + \dfrac{y^{2}}{4} = 1$ is:', '["$\\dfrac{5}{3}$","$\\dfrac{3}{5}$","$\\dfrac{\\sqrt{5}}{2}$","$\\dfrac{\\sqrt{5}}{3}$"]'::jsonb, 3, '$e = \sqrt{1 - \dfrac{4}{9}} = \dfrac{\sqrt{5}}{3}$.', 'Ellipse'),
  ('The eccentricity of the hyperbola $\dfrac{(y + 1)^{2}}{4} - \dfrac{(x + 1)^{2}}{1} = 1$ is:', '["$\\dfrac{\\sqrt{5}}{2}$","$5$","$\\dfrac{2}{\\sqrt{5}}$","$3$"]'::jsonb, 0, '$a^{2} = 4$, $b^{2} = 1$ and $e = \sqrt{1 + \dfrac{b^{2}}{a^{2}}} = \sqrt{\dfrac{5}{4}} = \dfrac{\sqrt{5}}{2}$.', 'Hyperbola'),
  ('Which of the following is a parametric representation of a hyperbola?', '["$x = a\\cos\\theta,\\ y = b\\sin\\theta$","$x = a\\sec\\theta,\\ y = b\\tan\\theta$","$x = a\\sin\\theta,\\ y = b\\cos\\theta$","$x = a\\cos\\theta,\\ y = a\\sin\\theta$"]'::jsonb, 1, 'Since $\sec^{2}\theta - \tan^{2}\theta = 1$, these give $\dfrac{x^{2}}{a^{2}} - \dfrac{y^{2}}{b^{2}} = 1$. The cosine/sine pair gives an ellipse.', 'Parametric Equations of Conics'),
  ('The parabola $y^{2} = 4ax$ passes through $(2, -4)$. Its focus is:', '["$(0, 2)$","$(4, 0)$","$(2, 0)$","$(0, 4)$"]'::jsonb, 2, '$16 = 4a(2)$ gives $a = 2$, so the focus is $(a, 0) = (2, 0)$.', 'Parabola'),
  ('The equation of the parabola with vertex at the origin and focus $\left(0, \dfrac{1}{2}\right)$ is:', '["$y^{2} = 2x$","$y^{2} = 4x$","$2y^{2} = x$","$x^{2} = 2y$"]'::jsonb, 3, 'The focus is on the $y$-axis with $a = \tfrac{1}{2}$, so $x^{2} = 4ay = 2y$.', 'Parabola'),
  ('The vertex of the parabola $5x^{2} - 20x - 2y + 21 = 0$ is:', '["$\\left(2, \\dfrac{1}{2}\\right)$","$\\left(\\dfrac{1}{2}, 2\\right)$","$(2, 1)$","$\\left(-2, \\dfrac{1}{2}\\right)$"]'::jsonb, 0, '$5(x - 2)^{2} - 20 = 2y - 21$ gives $5(x - 2)^{2} = 2y - 1$, i.e. $y = \dfrac{5}{2}(x - 2)^{2} + \dfrac{1}{2}$. The vertex is $\left(2, \tfrac{1}{2}\right)$.', 'Parabola'),
  ('The equation $16x^{2} + 9y^{2} - 44x + 42y + 49 = 0$ represents:', '["a parabola","an ellipse","a hyperbola","a circle"]'::jsonb, 1, '$x^{2}$ and $y^{2}$ have positive, unequal coefficients ($b^{2} - 4ac = -576 < 0$), so the conic is an ellipse.', 'Classification of Conics'),
  ('The focus of the parabola $(y - 4)^{2} = 2(x - 1)$ is:', '["$\\left(-\\dfrac{3}{2}, -3\\right)$","$\\left(1, -\\dfrac{3}{4}\\right)$","$\\left(\\dfrac{3}{2}, 4\\right)$","$\\left(1, \\dfrac{3}{4}\\right)$"]'::jsonb, 2, '$4a = 2$ gives $a = \tfrac{1}{2}$. The vertex is $(1, 4)$, so the focus is $\left(1 + \tfrac{1}{2}, 4\right) = \left(\tfrac{3}{2}, 4\right)$.', 'Parabola'),
  ('The circle with centre at the origin that passes through $(-1, 2)$ is:', '["$x^{2} + y^{2} = 25$","$x^{2} + y^{2} = 3$","$x^{2} + y^{2} = 4$","$x^{2} + y^{2} = 5$"]'::jsonb, 3, '$r^{2} = (-1)^{2} + 2^{2} = 5$.', 'Equation of a Circle'),
  ('The asymptotes of the conic $9x^{2} - 4y^{2} = 36$ are:', '["$y = \\pm\\dfrac{3}{2}x$","$x = \\pm\\dfrac{3}{2}y$","$x = \\pm\\dfrac{2}{3}x$","$y = \\pm\\dfrac{2}{3}x$"]'::jsonb, 0, '$\dfrac{x^{2}}{4} - \dfrac{y^{2}}{9} = 1$, so $y = \pm\dfrac{3}{2}x$.', 'Hyperbola'),
  ('The equation of the directrices of the ellipse $\dfrac{x^{2}}{a^{2}} + \dfrac{y^{2}}{b^{2}} = 1$ ($a > b$) is:', '["$x = \\dfrac{a}{e}$ only","$x = \\pm\\dfrac{a}{e}$","$y = \\pm\\dfrac{a}{e}$","$y = \\pm\\dfrac{b}{e}$"]'::jsonb, 1, 'The directrices are the two vertical lines at distance $\dfrac{a}{e}$ on either side of the centre.', 'Ellipse'),
  ('The foci of the ellipse $3x^{2} + y^{2} = 3$ are:', '["$(\\pm\\sqrt{3}, 0)$","$(0, \\pm3\\sqrt{2})$","$(0, \\pm\\sqrt{2})$","$(\\pm\\sqrt{2}, 0)$"]'::jsonb, 2, '$x^{2} + \dfrac{y^{2}}{3} = 1$ has $a^{2} = 3$ along the $y$-axis and $b^{2} = 1$, so $c^{2} = 2$ and the foci are $(0, \pm\sqrt{2})$.', 'Ellipse'),
  ('The distance between the two vertices of the conic $4y^{2} - 9x^{2} = 44$ is:', '["6","12","$4\\sqrt{3}$","$2\\sqrt{11}$"]'::jsonb, 3, '$\dfrac{y^{2}}{11} - \dfrac{x^{2}}{44/9} = 1$, so the vertices are $(0, \pm\sqrt{11})$ and the distance is $2\sqrt{11}$.', 'Hyperbola'),
  ('The equation of the parabola whose focus is $(2, 0)$ and whose directrix is $x + 2 = 0$ is:', '["$y^{2} = 8x$","$y^{2} = 4x$","$y^{2} = 20x$","$y^{2} = 12x$"]'::jsonb, 0, '$a = 2$ with vertex at the origin, so $y^{2} = 4ax = 8x$.', 'Parabola'),
  ('The length of the latus rectum of the parabola $3y^{2} - x - 18y + 27 = 0$ is:', '["8","$\\dfrac{1}{3}$","2","3"]'::jsonb, 1, '$3(y - 3)^{2} = x$ gives $(y - 3)^{2} = \tfrac{x}{3}$, so $4a = \tfrac{1}{3}$, which is the latus rectum.', 'Parabola'),
  ('The equation of the ellipse with a focus at $(1, 1)$, directrix $y = 4$ and eccentricity $e = \dfrac{1}{3}$ is:', '["$9x^{2} + 8y^{2} + 18x + 10y + 2 = 0$","$9x^{2} + 8y^{2} + 18x - 10y + 2 = 0$","$9x^{2} + 8y^{2} - 18x - 10y + 2 = 0$","$9x^{2} + 8y^{2} - 28y + 29 = 0$"]'::jsonb, 2, '$(x - 1)^{2} + (y - 1)^{2} = \tfrac{1}{9}(y - 4)^{2}$. Multiply by 9 and expand: $9x^{2} - 18x + 9 + 9y^{2} - 18y + 9 = y^{2} - 8y + 16$, giving $9x^{2} + 8y^{2} - 18x - 10y + 2 = 0$.', 'Conic as a Locus'),
  ('The equation of the hyperbola with centre $(4, 5)$, a focus at $(4, -5)$, transverse axis parallel to the $y$-axis and of length 8 is:', '["$\\dfrac{(x - 4)^{2}}{16} - \\dfrac{(y - 5)^{2}}{84} = 1$","$\\dfrac{(y - 5)^{2}}{16} - \\dfrac{(x - 4)^{2}}{100} = 1$","$\\dfrac{(y - 5)^{2}}{8} - \\dfrac{(x - 4)^{2}}{84} = 1$","$\\dfrac{(y - 5)^{2}}{16} - \\dfrac{(x - 4)^{2}}{84} = 1$"]'::jsonb, 3, '$2a = 8$ gives $a = 4$. The distance from the centre to the focus is $c = |5 - (-5)| = 10$, so $b^{2} = c^{2} - a^{2} = 100 - 16 = 84$.', 'Hyperbola'),
  ('The tangents to the ellipse $x^{2} + 2y^{2} = 19$ that are parallel to the line $x + 6y = 5$ are:', '["$x + 6y = \\pm 19$","$x + 6y = \\pm 5$","$6x + y = \\pm 19$","$x + 6y = \\pm \\dfrac{19}{6}$"]'::jsonb, 0, 'For $\dfrac{x^{2}}{19} + \dfrac{y^{2}}{19/2} = 1$ and slope $m = -\tfrac{1}{6}$, $c^{2} = a^{2}m^{2} + b^{2} = \dfrac{19}{36} + \dfrac{19}{2} = \dfrac{361}{36}$, so $c = \pm\dfrac{19}{6}$ and the tangents are $y = -\tfrac{x}{6} \pm \tfrac{19}{6}$, i.e. $x + 6y = \pm 19$.', 'Tangents to a Conic'),
  ('The tangents from $(-1, -1)$ to the parabola $x^{2} = 8y$ have gradients:', '["$2$ and $-1$","$\\dfrac{1}{2}$ and $-1$","$\\dfrac{1}{2}$ and $1$","$-2$ and $1$"]'::jsonb, 1, 'The tangent with gradient $m$ to $x^{2} = 8y$ is $y = mx - 2m^{2}$. Through $(-1, -1)$: $-1 = -m - 2m^{2}$, so $2m^{2} + m - 1 = 0$ and $m = \tfrac{1}{2}$ or $-1$.', 'Tangents to a Conic'),
  ('The tangent to the conic $x = -2e^{-t}$, $y = 3e^{t}$ at $t = 0$ is:', '["$3x + 2y + 12 = 0$","$2x + 3y - 5 = 0$","$3x - 2y + 12 = 0$","$3x - 2y - 12 = 0$"]'::jsonb, 2, 'At $t = 0$ the point is $(-2, 3)$. $\dfrac{dx}{dt} = 2e^{-t} = 2$ and $\dfrac{dy}{dt} = 3e^{t} = 3$, so the gradient is $\tfrac{3}{2}$: $y - 3 = \tfrac{3}{2}(x + 2)$, i.e. $3x - 2y + 12 = 0$.', 'Tangents to a Conic'),
  ('The normal to the conic $x = -2e^{-t}$, $y = 3e^{t}$ at $t = 0$ is:', '["$3x - 2y + 12 = 0$","$2x - 3y + 13 = 0$","$3x + 2y = 0$","$2x + 3y - 5 = 0$"]'::jsonb, 3, 'The tangent gradient is $\tfrac{3}{2}$, so the normal gradient is $-\tfrac{2}{3}$: $y - 3 = -\tfrac{2}{3}(x + 2)$, i.e. $2x + 3y - 5 = 0$.', 'Tangents to a Conic'),
  ('For the conic $5x^{2} + 4y^{2} - 30x + 8y + 45 = 0$, the centre is:', '["$(3, -1)$","$(-3, 1)$","$(3, 1)$","$(5, 4)$"]'::jsonb, 0, 'Completing the square: $5(x - 3)^{2} + 4(y + 1)^{2} = 4$, so the centre is $(3, -1)$.', 'Ellipse'),
  ('For the ellipse $5(x - 3)^{2} + 4(y + 1)^{2} = 4$, the equations of the directrices are:', '["$y = 3 \\pm \\sqrt{5}$","$y = -1 \\pm \\sqrt{5}$","$x = 3 \\pm \\sqrt{5}$","$y = -1 \\pm \\dfrac{1}{\\sqrt{5}}$"]'::jsonb, 1, '$\dfrac{(x - 3)^{2}}{4/5} + \dfrac{(y + 1)^{2}}{1} = 1$ has its major axis vertical with $a^{2} = 1$, $c^{2} = 1 - \tfrac{4}{5} = \tfrac{1}{5}$. The directrices are $y + 1 = \pm\dfrac{a^{2}}{c} = \pm\sqrt{5}$.', 'Ellipse'),
  ('The conic with directrix $x + y = 6$, focus $(-2, 3)$ and eccentricity $e = \dfrac{1}{3}$ has the equation:', '["$17x^{2} + 2xy + 17y^{2} + 84x - 96y + 198 = 0$","$17x^{2} - 2xy + 17y^{2} - 84x + 96y + 198 = 0$","$17x^{2} - 2xy + 17y^{2} + 84x - 96y + 198 = 0$","$18x^{2} + 18y^{2} + 72x - 108y + 234 = 0$"]'::jsonb, 2, '$\sqrt{(x + 2)^{2} + (y - 3)^{2}} = \dfrac{1}{3}\cdot\dfrac{|x + y - 6|}{\sqrt{2}}$. Squaring and multiplying by 18: $18[(x + 2)^{2} + (y - 3)^{2}] = (x + y - 6)^{2}$, which simplifies to the equation shown.', 'Conic as a Locus'),
  ('The plane through the point $(1, -1, 2)$ with normal $2\mathbf{i} - 3\mathbf{j} + 4\mathbf{k}$ is:', '["$2x + 3y - 4z = 13$","$3x - 2y + 4z = 13$","$4x - 2y - 3z = 13$","$2x - 3y + 4z = 13$"]'::jsonb, 3, '$2(1) - 3(-1) + 4(2) = 13$, so the plane is $2x - 3y + 4z = 13$.', 'Planes'),
  ('The equation of the plane through $P(2, -1, 1)$, $Q(3, 2, -1)$ and $R(-1, 3, 2)$ is:', '["$11x + 5y + 13z = 30$","$11x - 5y + 13z = 30$","$11x - 5y - 13z = 30$","$11x + 5y + 13z = 13$"]'::jsonb, 0, '$\overrightarrow{PQ} = (1, 3, -2)$ and $\overrightarrow{PR} = (-3, 4, 1)$. The normal is $\overrightarrow{PQ}\times\overrightarrow{PR} = (11, 5, 13)$, and $11(2) + 5(-1) + 13(1) = 30$.', 'Planes'),
  ('The angle between the vectors $\mathbf{a} = \mathbf{i} + 2\mathbf{j} - 2\mathbf{k}$ and $\mathbf{b} = -2\mathbf{i} + 3\mathbf{j} + 6\mathbf{k}$ is:', '["$\\cos^{-1}\\left(\\dfrac{8}{21}\\right)$","$\\cos^{-1}\\left(-\\dfrac{8}{21}\\right)$","$\\cos^{-1}\\left(\\dfrac{1}{8}\\right)$","$\\cos^{-1}\\left(\\dfrac{21}{8}\\right)$"]'::jsonb, 1, '$\mathbf{a}\cdot\mathbf{b} = -2 + 6 - 12 = -8$, $|\mathbf{a}| = 3$ and $|\mathbf{b}| = 7$, so $\cos\theta = -\dfrac{8}{21}$.', 'Dot Product'),
  ('The angle between $\mathbf{a} = 2\mathbf{i} - 3\mathbf{j} + 5\mathbf{k}$ and $\mathbf{b} = -6\mathbf{i} + 9\mathbf{j} - 15\mathbf{k}$ is:', '["$0$","$\\dfrac{\\pi}{2}$","$\\pi$","$\\dfrac{\\pi}{3}$"]'::jsonb, 2, '$\mathbf{b} = -3\mathbf{a}$, so the vectors are parallel and point in opposite directions: the angle is $\pi$.', 'Dot Product'),
  ('The vector product $2\mathbf{j}\times\mathbf{i}$ is:', '["$2\\mathbf{k}$","$\\mathbf{k}$","$-\\mathbf{k}$","$-2\\mathbf{k}$"]'::jsonb, 3, '$\mathbf{j}\times\mathbf{i} = -\mathbf{k}$, so $2\mathbf{j}\times\mathbf{i} = -2\mathbf{k}$.', 'Vector Product'),
  ('The area of the triangle with vertices $(0, 0)$, $(a, b)$ and $(-b, a)$ is:', '["$\\dfrac{1}{2}(a^{2} + b^{2})$","$a^{2} + b^{2}$","$2a^{2} + 2b^{2}$","$4a^{2} + 4b^{2}$"]'::jsonb, 0, 'Area $= \tfrac{1}{2}|a\cdot a - (-b)\cdot b| = \tfrac{1}{2}(a^{2} + b^{2})$.', 'Area of a Triangle'),
  ('Given $\mathbf{u}(t) = \sin t\,\mathbf{i} + \cos t\,\mathbf{j} + 3\mathbf{k}$ and $\mathbf{v}(t) = t\mathbf{i} - 2\mathbf{k}$, the scalar product $\mathbf{u}\cdot\mathbf{v}$ is:', '["$t\\sin t + 6$","$t\\sin t - 6$","$t\\cos t + 6$","$t\\cos^{2}t + 3$"]'::jsonb, 1, '$\mathbf{u}\cdot\mathbf{v} = (\sin t)(t) + (\cos t)(0) + (3)(-2) = t\sin t - 6$.', 'Dot Product'),
  ('The vectors $\mathbf{v} = 3\mathbf{i} - 2\mathbf{j}$ and $\mathbf{w} = 4\mathbf{i} - p\mathbf{j}$ are parallel when $p$ equals:', '["$-\\dfrac{8}{3}$","$\\dfrac{3}{8}$","$\\dfrac{8}{3}$","$6$"]'::jsonb, 2, 'Parallel vectors have proportional components: $\dfrac{4}{3} = \dfrac{-p}{-2}$, so $p = \dfrac{8}{3}$.', 'Parallel Vectors'),
  ('The position vectors of $P$ and $Q$ are $\mathbf{i} + 3\mathbf{j} - 7\mathbf{k}$ and $5\mathbf{i} - 2\mathbf{j} + 4\mathbf{k}$. The modulus of $\overrightarrow{PQ}$ is:', '["$\\sqrt{26}$","$\\sqrt{162}$ ÷ 2","$11$","$9\\sqrt{2}$"]'::jsonb, 3, '$\overrightarrow{PQ} = 4\mathbf{i} - 5\mathbf{j} + 11\mathbf{k}$ and $|PQ| = \sqrt{16 + 25 + 121} = \sqrt{162} = 9\sqrt{2}$.', 'Vectors in Three Dimensions'),
  ('A particle has position vector $\mathbf{r}(t) = (3\sin 2t,\ 3\cos 2t,\ 2t)$. Its speed is:', '["$2\\sqrt{10}$","$6$","$\\sqrt{40}\\,t$","$12$"]'::jsonb, 0, '$\mathbf{v} = (6\cos 2t,\ -6\sin 2t,\ 2)$ and $|\mathbf{v}| = \sqrt{36 + 4} = \sqrt{40} = 2\sqrt{10}$.', 'Vector Calculus'),
  ('For the particle with $\mathbf{r}(t) = (3\sin 2t,\ 3\cos 2t,\ 2t)$, the acceleration is ______ the velocity.', '["parallel to","perpendicular to","equal to","in the opposite direction to"]'::jsonb, 1, '$\mathbf{a} = (-12\sin 2t,\ -12\cos 2t,\ 0)$. $\mathbf{v}\cdot\mathbf{a} = -72\sin 2t\cos 2t + 72\sin 2t\cos 2t + 0 = 0$, so the vectors are orthogonal.', 'Vector Calculus'),
  ('The line through $A(2, -1, 3)$ parallel to $\overrightarrow{BC}$, where $B = (3, 2, -4)$ and $C = (-1, 3, -2)$, is:', '["$\\dfrac{x - 2}{4} = \\dfrac{y + 1}{1} = \\dfrac{z - 3}{2}$","$\\dfrac{x - 3}{-4} = \\dfrac{y - 2}{1} = \\dfrac{z + 4}{2}$","$\\dfrac{x - 2}{-4} = \\dfrac{y + 1}{1} = \\dfrac{z - 3}{2}$","$\\dfrac{x - 2}{-4} = \\dfrac{y + 1}{-1} = \\dfrac{z - 3}{2}$"]'::jsonb, 2, '$\overrightarrow{BC} = (-1 - 3,\ 3 - 2,\ -2 + 4) = (-4, 1, 2)$ is the direction vector; the line passes through $A$.', 'Vector Equation of a Line'),
  ('A vector $\mathbf{v}$ has its tail at $(-1, -3)$ and its head at $(3, 9)$. Expressing $\mathbf{v}$ in terms of $\mathbf{a} = (-2, 3)$ and $\mathbf{b} = (3, 9)$ gives:', '["$\\mathbf{v} = \\mathbf{a} + \\mathbf{b}$","$\\mathbf{v} = 2\\mathbf{a} + \\mathbf{b}$","$\\mathbf{v} = \\dfrac{4}{3}\\mathbf{a}$","$\\mathbf{v} = \\dfrac{4}{3}\\mathbf{b}$ (with no $\\mathbf{a}$ component)"]'::jsonb, 3, '$\mathbf{v} = (3 + 1,\ 9 + 3) = (4, 12)$. Solving $(4, 12) = \alpha(-2, 3) + \beta(3, 9)$: $-2\alpha + 3\beta = 4$ and $3\alpha + 9\beta = 12$ give $\alpha = 0$ and $\beta = \tfrac{4}{3}$.', 'Vectors in Two Dimensions')
),
tgt as (
  select subject_id, subject_name, faculty, department, level, semester, units
    from public.cbt_questions
   where subject_name ilike 'MTH 102%' and subject_id not like '%coming-soon'
   limit 1
)
insert into public.cbt_questions
  (subject_id, subject_name, institution, faculty, department, level,
   question, options, correct_index, explanation, topic, is_general, semester, units)
select coalesce(t.subject_id, 'mth-102-vectors-geometry-dynamics'),
       coalesce(t.subject_name, 'MTH 102: Vectors, Coordinate Geometry & Elementary Dynamics'),
       'University of Nigeria, Nsukka',
       coalesce(t.faculty, 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Social Sciences, Faculty of Education'),
       coalesce(t.department, 'Mathematics'),
       coalesce(t.level, '100 Level'),
       s.question, s.options, s.correct_index, s.explanation, s.topic, false,
       coalesce(t.semester, 'second'),
       coalesce(t.units, 3)
  from src s
  left join tgt t on true
 where not exists (
   select 1 from public.cbt_questions c
    where c.subject_id = coalesce(t.subject_id, 'mth-102-vectors-geometry-dynamics') and c.question = s.question);

select subject_id, subject_name, count(*) as questions
  from public.cbt_questions
 where subject_name ilike 'MTH 102%' and subject_id not like '%coming-soon'
 group by 1, 2;

